COLLDATA("tadabburur","ur",[[534,"§الواقعہ ، الرحمن\ndeeds\nاللہ سے آخرت میں اپنے بلند مقام کے لئے دعا کریں.\nآج سب سے پہلے مسجد میں کسی ایک پنج وقتہ فرض نماز کے لئے داخل ہوں.\nآج اپنے بھائیوں میں سب سے پہلے اپنے والدین کے سر کا بوسہ لینے والا بنیں.\nguid\nقیامت کے دن کی ہولناکیوں کا تصور کیجئے.\nاچھے کاموں میں مقابلہ آرائی کا اونچا مقام ہے.\nبدلہ کام کی نوعیت کے اعتبار سے ہوتا ہے (جیسی کرنی ویسی بھرنی).\nrefl\nحُورٞ مَّقۡصُورَٰتٞ فِي ٱلۡخِيَامِ ٧٢\nالحور: الحَوراء کی جمع ہے: (نہایت گوری) اور مَقْصُوْرٰت کا مطلب ہے باپردہ ، کیونکہ گھروں میں رہنے والی باپردہ خواتین قابل تعریف ہوتی ہیں، اور جو گھروں سے بکثرت نکلتی ہیں وہ لائق مذمت ہیں۔ (ابن جزی:۲؍۳۹۷)\nکس طرح یہ آیت خواتین کو گھروں میں رہنے پر ابھارتی ہے؟\nإِذَا وَقَعَتِ ٱلۡوَاقِعَةُ ١\n(واقعہ قیامت کا ایک نام ہے) اور قیامت کو (واقعہ) کا نام اس لئے دیاگیا ہے کہ وہ قطعی طور سے واقع ہونے والی ہے، یا اس کے عنقریب واقع ہونے کی وجہ سے ، یا اس میں بہت زیادہ مشکلات واقع ہونے کی وجہ سے۔ (الشوکانی:۵؍۱۴۷)\nروز قیامت کو واقعہ کا نام کیوں دیا گیا ؟\nخَافِضَةٞ رَّافِعَةٌ ٣\n(قیامت) کچھ لوگوں کو جہنم میں نیچے ڈالے گی اور دوسروں کو جنت میں بلند کرے گی، ابن عباس فرماتے ہیں کہ: جو دنیا میں بلند مرتبہ والے تھے ان کو نیچے کرےگی،اور جو دنیا میں کمزور تھے ان کو اونچا کرے گی۔(البغوی:۴؍۳۰۱)\nقیامت کے دن اوپر نیچے کرنا کس طرح ہوگا؟\nوَالسّٰبِقُوْنَ السّٰبِقُوْنَ ١٠\nجس نے دنیا میں اچھے کام میں مقابلہ کیا اور اس میں آگے بڑھ گیا تو وہ آخرت میں نوازش (الٰہی) کی طرف آگے بڑھنے والوں میں ہوگا، کیونکہ کام کا بدلہ کام کے اعتبار سے ہوتا ہے، جیسی کرنی ویسی بھرنی۔ (ابن کثیر:۴؍۲۸۵)\nمذکورہ لوگ کیوں آخرت میں سابقین میں سےکیوں ہوں گے؟\nثُلَّةٞ مِّنَ ٱلۡأَوَّلِينَ ١٣ وَقَلِيلٞ مِّنَ ٱلۡأٓخِرِينَ ١٤\n(ثلة من الأولين) یعنی بہت بڑی جماعت اس امت کے اگلوں میں سے اور ان کے علاوہ میں سے(وقليل من الآخرين). (اور تھوڑے سے پچھلے لوگوں میں سے) یہ اس امت کے اولین لوگوں کی عمومی فضیلت پر دلالت کرتی ہے ان کے مقابل جو بعدوالے ہیں، کیونکہ پہلے لوگوں میں مقربین کی تعداد بعد والوں کے بہ نسبت زیادہ ہے، مقربین بہت خاص لوگ ہوتے ہیں۔ (السعدی: ۸۳۳)\nیہ دونوں آیتیں فضیلت یافتہ صدی والوں (صحابہ، تابعین، اتباع تابعین) کی فضیلت پر کیسے دلالت کرتی ہیں؟ وجہ استدلال واضح کیجئے\nعَلَىٰ سُرُرٖ مَّوۡضُونَةٖ ١٥ مُّتَّكِـِٔينَ عَلَيۡهَا مُتَقَٰبِلِينَ ١٦\nجب لوگوں کی بہت زیادہ تعداد اکٹھا ہوجاتی ہے تو بعض لوگوں کی پیٹھ بعض کی طرف ہوتی ہے، (جب عموما ایسا ہی ہوتا ہے اس لئے) اللہ نے یہ خبر دی کہ جنت والوں کا اکٹھا ہونا اس کے برخلاف ہےچنانچہ فرمایا: (متقابلين) وہ آمنے سامنے ہوں گے نہ دوری ہوگی نہ ایک دوسرے کےپیچھے ہوں گےنہ کوئی کسی کے سر کے پچھلے حصے (گدی) کو دیکھے گا۔ اور نہ ہی ایک دوسرے سے نفرت کریں گے۔ (البقاعی:۱۹؍۲۰۳)\n(متقابلين) کس چیز پر دلالت کرتی ہے؟\nمُّتَّكِـِٔينَ عَلَيۡهَا مُتَقَٰبِلِينَ ١٦\nہر ایک کا چہرہ اس کے ساتھی کی طرف ہوگا، ایسا دلوں کی صفائی، حسن اخلاق اور دلوں کا ایک دوسرے کو قبول کرنے کی وجہ سے ہوگا۔ (السعدی: ۸۳۳)\nیہ آیت دلالت کرتی ہے کہ جنت والوں کے دل صاف ستھرے ہوں گے، اور ان کے دلوں سے بغض اور کینہ نکال دیا جائے گا، اس کی وضاحت کیجئے؟\nwords\nخَيرَاتٌپاكيزه اخلاق والي بيوياں.\nحُورٌسفيد اور خوبصورت عورت.\nمَقصُورَاتٌمستور /پرده كئے هوئے.\nيَطمِثهُنَّان سے وطي كي هوگي/ ان كو چھوا هوگا.\nرَفرَفٍ خُضرسبز تكئے(ايسے تكئے جن پر سبز غلاف هوں گے).\nوَعَبقَرِيٍّفرش / بچھونا.\nرُجَّتِوه حركت دي جائے گي.\nوَبُسَّتِاڑا ديے جائيں گے.\nثُلَّةٌايك بڑي جماعت.\nمَوضُونَةٍسونے کے تاروں سے بنے ہوئے تخت."],[535,"§الواقعہ\ndeeds\nاللہ سے دعا فرمائیں کہ آپ اصحاب یمین میں سے ہوجائیں.\nکسی فقیرکو میوہ اور گوشت کا صدقہ کیجئے تاکہ آپ جنت کے گوشت اور میوے پا سکیں.\nآج کے دن اپنی زندگی میں کسی آسائش پر صبر کیجئے.\nguid\nبیوی کا شوہر سے محبت کرنا۔گھریلو تعلقات میں استحکام کا سبب ہے.\nاللہ نے اپنی اطاعت کرنے والوں کی عزت افزائی کے لئے جو اونچا مقام عطا کیا ہے، یہ دنیا میں ان کے اچھے کاموں اور صبر کا بدلہ ہے.\nبائیں طرف والوں کی خصلت سے دوری اختیار کرنا اور ان سے اللہ کی پناہ چاہنا.\nrefl\nوَفَٰكِهَةٖ مِّمَّا يَتَخَيَّرُونَ ٢٠ وَلَحۡمِ طَيۡرٖ مِّمَّا يَشۡتَهُونَ ٢١\nکھانے میں پھل پہلے کھاناطبی اعتبار سے اچھا ہوتا ہے ۔ کیونکہ یہ کھانے میں زیادہ آسان اور نیچے جانے میں زیادہ تیز رفتار ہوتاہے اور ہضم کے لئے معدے میں زیادہ وقت نہیں لگتا۔ حکماء کے مطابق سخت کھانے کے بعد سیال کھانا پیٹ میں داخل کرنا ہیضہ کا ایک سبب ہے ۔(آلوسی:۱۴؍۱۳۷)\nمیوہ کو گوشت پر کیوں مقدم رکھا گیا؟\nوَحُورٌ عِينٞ ٢٢ كَأَمۡثَٰلِ ٱللُّؤۡلُوِٕ ٱلۡمَكۡنُونِ ٢٣\nحورعین کو سفیدی میں موتیوں سے تشبیہ دی گئی اور(اللؤلؤ)کی صفت جو(المكنون)ذکر کی گئی ہے وہ اس لئے کہ اس کے سبب خوبصورتی تبدیل نہیں ہوتی ۔\nحور عین کو چھپے ہوئے موتی سے تشبیہ دینے کا کیا مقصد ہے؟\nوَظِلّٖ مَّمۡدُودٖ ٣٠\nیعنی سایاپھیلا ہوا ہوگا ختم نہیں ہوگا۔ کیونکہ دھوپ اس سائے کو زائل نہیں کر سکتی رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے : جنت میں ایک ایسا درخت ہوگا جس کے سائے میں سوار سو سال تک چلتا رہے تب بھی اس کی مسافت طے نہ کر سکے گا۔ تم چاہو تو (وظل ممدود)پڑھ کر مزید یقین حاصل کرسکتےہو۔(ابن جزی:۲؍۴۰۱)\nنبوی تفسیر کے درمیان ایک ایسی مثال ذکر کیجئے جس سے روز قیامت پھیلے ہوئے سائے کی وضاحت ہوتی ہو؟\nلَّا مَقۡطُوعَةٖ وَلَا مَمۡنُوعَةٖ ٣٣\nابن عباس رضی اللہ عنہ کا فرمان ہے : تم توڑوگے تو ختم نہ ہوگا، جو کوئی لینا چاہے گا اسے کوئی روکنے والا نہ ہوگا۔ بعض کے بقول زمانوں کے سبب ختم نہ ہوگا، قیمتوں کے سبب حصول میں رکاوٹ پیدا نہ ہوگی۔جیسا کہ دنیا کے بیشتر پھل سردیاں آتے ہی ختم ہوجاتے ہیں اور انہیں مہنگی قیمت دیئے بغیرحاصل کرنا آسان نہیں ہوتا۔ (البغوی:۴؍۳۰۶)\n(لا مقطوعة ولا ممنوعة)سے کیا مراد ہے؟\nعُرُبًا أَتۡرَابٗا ٣٧\nعرب ،عروب کی جمع ہے ۔ مراد اپنے شوہر سے محبت کرنے والی ہے، مبرد کا کہنا ہے :وہ اپنے شوہر کی عاشق ہوگی۔ (الشوکانی:۵؍۱۵۳)\nآیت میں (عُرُبًا)کے کیامعنی ہیں ؟\nوَظِلّٖ مِّن يَحۡمُومٖ ٤٣ لَّا بَارِدٖ وَلَا كَرِيمٍ ٤٤\nیعنی اس میں کوئی ٹھنڈک ہوگی نہ کوئی لطف۔ مقصود یہ ہے کہ وہاں غم اور دکھ، تکلیف اور برائی ہوگی اس میں بھلائی ممکن ہی نہیں۔ کیونکہ کسی چیز کی ضد کی نفی سے دوسری الٹی صورت کا اثبات لازم آتاہے۔(السعدی:۸۳۴)\nجہنم کے سائے سے ٹھنڈک اور لطف کی نفی سے کیا مراد ہے ؟\nإِنَّهُمۡ كَانُواْ قَبۡلَ ذَٰلِكَ مُتۡرَفِينَ ٤٥\nبائیں طرف والوں کو (مُتْرَفِيْنَ) قراردیاکیونکہ ان میں سے کوئی بھی ‘‘ترف’’ یعنی آسودگی کے تکبر سے خالی نہیں تھااگر چہ کھانے پینے اور عورتوں کی یہ متکبرانہ آسودگی بعض حالات اور بعض اوقات میں ہی پائی گئی۔یا پھر ایسا ہو کہ جب انہوں نے جلد حاصل ہونے والی زندگی کی فکر پر نظر جمالی تو اللہ کے رسول صلی اللہ علیہ وسلم جس چیز کی دعوت دے رہے تھےاس کی صحت میں نظر و استدلال کرنے سے انہیں محروم کردیا۔ یہی سبب ہے کہ اللہ نے دنیا میں ان کی متکبرانہ آسودگی والی وجہ کو ان کے مذکورہ جزا کا سبب قراردیا ۔(ابن عاشور:۲۷؍۳۰۶)\nمتکبرانہ آسودگی کی خطرناکی اور اس کے اخروی انجام کی وضاحب کیجئے ؟\nwords\nلاَ يُصَدَّعُونَ عَنهَااس سے سر ميں درد نه هوگا.\nوَلاَ يُنزِفُونَاور نه هي ان كي عقول ختم هوں گي.\nالمَكنُونِچھپائے هوئے موتي.\nسِدرٍ مَخضُودٍبغير كانٹے كے بيري.\nوَطَلحٍ مَنضُودٍتہہ بہ تہہ کیلے ہوں گے.\nعُرُبًامحبت كرنے والياں (اپنے شوهروں سے).\nأَترَابًاهم عمر."],[536,"§الواقعہ\ndeeds\nجب کوئی کھاناکھائیں تو اس کے مراحل شمار کریں کہ کن کن مرحلوں سے ہو کر یہ کھانا گزرا ہے تاآنکہ کھانےلائق ہو سکاپھر اس پر اللہ کی تعریف کیجئے.\nجب بھی پانی پیجئے اللہ کی تعریف کیجئے.\nرکوع میں آیت کی تفسیر کا تصور کرتے ہوئے ‘‘سُبْحَانَ رَبِّيَ الْعَظِيْم’’ پڑھئے.\nguid\nاللہ نے ہم پر جو انعام کیا اور پیدائش ،رزق ،تدبیر کے حوالے سے جو مہربانی فرمائی اس پر اللہ کے لئے بندگی کا اعتراف.\nجس طرح دنیا کی آگ میں بندوں کے لئے فائدہ ہے سو اس میں آخرت کی آگ کے ذکر سے ان کے لئے نصیحت کا فائدہ ہے.\nrefl\nنَحۡنُ قَدَّرۡنَا بَيۡنَكُمُ ٱلۡمَوۡتَ وَمَا نَحۡنُ بِمَسۡبُوقِينَ ٦٠\nیعنی ایک معین مقدار ہر ایک کے لئے واجب ہے جس سے کوئی بھی تجاوز نہیں کر سکتا۔ سو کسی کی عمر ہم کم کردیتے ہیں حالانکہ بدن کی طاقت اور مزاج کی صحت میں وہ جوانی پر ہوتا ہے اور کسی کی عمر ہم لمبی کردیتے ہیں حالانکہ ضعف بدن اور طبیعت کی خرابی سے وہ نڈھال ہوتاہے ۔ اور تم سب اس بات کے اقراری ہو کہ اللہ نے اپنے افعال کی ترتیب، حکمت بالغہ، قدرت،اور کمال کے تقاضے پر قائم رکھی ہے۔(البقاعی:۱۹؍۲۲۱)\n(نحن قدرنا بينكم الموت) کا کیامعنی ہے؟\nوَلَقَدۡ عَلِمۡتُمُ ٱلنَّشۡأَةَ ٱلۡأُولَىٰ فَلَوۡلَا تَذَكَّرُونَ ٦٢\nاللہ تعالیٰ اپنے فرمان (فلولا تذكرون) میں یہ کہہ رہا ہے کہ : اے لوگو! بھلا تم نصیحت کیوں نہیں پکڑتے جبکہ تم یہ جانتے ہو کہ وہ ذات جس نے تمہیں جب کچھ نہ تھے تو پہلی دفعہ پیدا فرمایا۔اب بھلااس کے لئے یہ بات کیوں مشکل ہوگئی کہ تمہاری موت اور تمہارے فنا ہوجانے کے بعد دوبارہ زندہ کرسکے۔ (الطبری:۲۳؍۱۳۸)\nاللہ تعالیٰ نے پہلی پیدائش اور نصیحت کو ملا کر کیوں بیان فرمایا؟\nءَأَنتُمۡ تَزۡرَعُونَهُۥٓ أَمۡ نَحۡنُ ٱلزَّٰرِعُونَ ٦٤\nیہ آیت دو معاملات پر مشتمل ہے ان میں سے ایک چیز ہے ان پر یہ احسان جتلانا کہ اللہ نے ان کی کھیتی لگائی اور انہوں نے اس کے ذریعہ زندگی گزاری۔ ایسا اس لئے کیا تاکہ وہ خود پر اللہ کی نعمت کا شکر یہ ادا کریں۔ دوسری چیز اعتبار کو قطعی بنادینے والی دلیل ہے ۔ وہ اس طرح کہ دانوں کے بکھرجانے کے بعد انہیں کائی اور پھپھوند کی صورت سے اٹھا کرکھڑے پودوں کی صورت بخشی تا آنکہ وہ ہری فصل میں تبدیل ہوگئی پھر پہلی صورت کے مقابلے اسے پختہ اور مضبوط کردیا۔ سو جو مر گیا ہے اسے دوبارہ پیدا کرنا تو اور آسان ہے۔ اس میں فطرت سلیمہ رکھنے والوں کے لئے اطمینان بخش دلیل ہے۔(القرطبی:۲؍۲۱۱)\nمختصر انداز میں کھیتی اگانے کے سلسلے میں اللہ کے احسان کا ذکر کیجئے ؟\nأَفَرَءَيۡتُمُ ٱلۡمَآءَ ٱلَّذِي تَشۡرَبُونَ ٦٨\nپانی کے منافع اور فوائد کی کثرت کے باوجود اللہ نےصر ف پینے کا فائدہ ذکر کیا اس لئے کہ ہر چیز کے فائدے سے پانی پینے کا فائدہ زیادہ اور اہم ترین ہے۔(الشوکانی:۵؍۱۵۸)\nپانی کے بہتیرے فوائد کے باوجود آیت میں صرف پینے کا ذکر کیوں کیا گیا ہے؟\nأَفَرَءَيۡتُمُ ٱلۡمَآءَ ٱلَّذِي تَشۡرَبُونَ ٦٨ ءَأَنتُمۡ أَنزَلۡتُمُوهُ مِنَ ٱلۡمُزۡنِ أَمۡ نَحۡنُ ٱلۡمُنزِلُونَ ٦٩\nاللہ کا یہ قول (أأنتم أنزلتموه من المزن) اس بات پر دلالت کرتا ہے کہ زمین کے اندر ٹھہرا ہوا پانی جو چشموں ،کنوؤں وغیرہ کی صورت میں نکل رہا ہے ان سب کی اصل یہ ہے کہ ساراپانی بادلوں سے ناز ل ہوا ہے اور اللہ نے اسے زمین میں اپنی مخلوق کے لئے ذخیرہ کررکھا ہے۔(الشنقیطی:۷؍۵۳۴)\nکنوئیں اور چشمے وغیرہ سے نکلنے والے پانی جو زمین کے اندر موجود ہیں وہ اصلاً کہاں سے آتے ہیں؟\nنَحۡنُ جَعَلۡنَٰهَا تَذۡكِرَةٗ وَمَتَٰعٗا لِّلۡمُقۡوِينَ ٧٣\n(المقوين) معنی ہے ‘‘المسافرين’’ یعنی سفر کرنے والے۔ اللہ نے مسافر وں کا ذکر بطور خاص کیاہے کیونکہ دوسروں کے مقابلے اس کا فائدہ مسافروں کے حق میں عظیم تر ہے اور ممکن ہے اس کا سبب یہ ہو کہ دنیا کل کی کل سفر کا مقام ہے بندہ پیدائش سے ہی اپنے رب کی طرف مسافر ہوتاہے۔(السعدی:۸۳۵-۸۳۶)\nآگ سے فائدہ حاصل کرنے میں مسافر کا خصوصی ذکر کیوں ہوا؟\nفَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِيمِ ٧٤\nنعمتوں کے ذکر کے بعد اللہ تعالیٰ کی تعظیم و تنزیہہ دراصل اللہ کی مدح کا درجہ رکھتی ہے۔ کیونکہ یہ چیز حقیقت میں نعمت دینے والے کا شکر ہے۔(الألوسی :۱۴؍۱۵۰)\nنعمتوں کے بیان کے بعد تسبیح کاحکم کس چیز پر دلالت کرتا ہے ؟\nwords\nزَقُّومٍزقوم ؛ جهنم ميں اگنے والا سب سے برا درخت.\nشُربَ الهِيمِبيمار پياسے اونٹ كي طرح پينا.\nبِمَسبُوقِينَعاجز آنے والے.\nتَفَكَّهُونَاپني فصل پر آنے والي مصيبت پر تعجب كرتے هو.\nإِنَّا لَمُغرَمُونَبے شك هم گھاٹا پانے والے هيں / عذاب ميں هيں.\nالمُزنِبادل.\nأُجَاجًاسخت نمكين.\nتُورُونَتم آگ جلاتے هو."],[537,"§الواقعہ ، الحديد\ndeeds\nمسجد کی الماریوں میں ترتیب سے رکھ کر اور گردوغبار صاف کرکے قرآن پاک کا ادب و احترام کیجئے!\nکسی بیمار کے یہاں تشریف لے جائیں یا کسی قبرستان یا مردوں کے غسل خانے کی زیارت کریں.\nقرآن کی تلاوت سے پہلے وضو کیجئے.\nguid\nاللہ کے دشمنوں کے ساتھ ان کے کھلم کھلا کفر اور وحی الٰہی کو جھٹلانے کے باوجود مداہنت برتنا جھٹلانے کی ہی ایک قسم ہے.\nاللہ کے بہت زیادہ قریبی لوگوں کا بدلہ بڑا عظیم ہوگا.\nاسماء حسنیٰ سیکھنے اور ان کے ذریعہ عبادت کی حرص رکھنا.\nrefl\nإِنَّهُۥ لَقُرۡءَانٞ كَرِيمٞ ٧٧\nیعنی اللہ نے قرآن پاک کو احترام بخشا اسے عزت دی اور اس کا درجہ بلند فرمایا۔اور اسے جھوٹ ،جادو،کہانت سے محفوظ رکھ کر مقدس بنایا۔ کہا گیا ہے کہ چونکہ اس میں بڑے معاملات اور اعلیٰ اخلاقیات کی چیزیں موجود ہیں اس لئے (كَرِيْمٌ) کہا۔ یہ بھی قول ہے کہ حافظ قرآن کی چونکہ عزت ہوتی ہے اور قاری قرآن کی تعظیم کی جاتی ہے اس لئے کریم کہا۔ واحدی نے اہل بلاغت سے بیان کیا ہے : قرآن کی وصف جو کریم بیان ہوئی وہ اس لئے کہ قرآن حق تک پہنچانے والے دلائل کے ذریعہ بہت زیادہ بھلائیاں عطا کرتا ہے۔ ازہری کا قول ہے : تعریف کی جانے والی چیزوں کے لئے کریم ایک جامع نام ہے اور چونکہ قرآن کریم میں علم و حکمت ، بیان و ہدایت موجود ہے اس لئے اس کی تعریف کی جاتی ہے۔ (الشوکانی:۵؍۱۶۰)\nقرآن کے(كَرِيْمٌ) ہونے کے کچھ اسباب بیان کیجئے؟\nإِنَّهُۥ لَقُرۡءَانٞ كَرِيمٞ ٧٧ فِي كِتَٰبٖ مَّكۡنُونٖ ٧٨ لَّا يَمَسُّهُۥٓ إِلَّا ٱلۡمُطَهَّرُونَ ٧٩\nآیت کریمہ میں اس بات کا بڑا لطیف اشارہ موجود ہے کہ اس کے معانی کا ادراک اور اس کامفہوم صرف صاف ستھرے دلوں کو حاصل ہوسکتا ہے۔ بدعات و مخالفات کی نجاستوں سے آلودہ دل اس کے معانی سے قطعی محروم ہوتا ہے، ایسا دل کما حقہ قرآن کو نہیں سمجھ سکتا۔(ابن القیم :۳؍۱۲۰)\nفہم قرآن کے لئے دل کی صفائی مطلوب ہے۔ آیتوں کی روشنی میں اس کی وضاحت کیجئے ؟\nتَنزِيلٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ ٨٠\nتنزیل کی نسبت اس کی ربوبیت کی طرف کی گئی ہے ، وہ ربوبیت جو تمام جہانوں کے لئے ہے ۔ وہ ربوبیت جو ان کی ملکیت کو لاز م ہے ، ان میں اس کے تصرف کو لاز م ہے ، ان پر اس کا حکم چلنے کو لازم ہے۔ تو مخلوق کے ساتھ جس کا معاملہ یوں ہو تو اس کی کامل ربوبیت کی شان سے بھلا یہ بات کیسے میل کھا سکتی ہے کہ وہ ان لوگوں کو یونہی بیکار و بے مقصد چھوڑ دے ،انہیں بلاوجہ پیدا فرمائے، انہیں کچھ حکم کرے نہ کسی بات سے روکے ، انہیں ثواب دے نہ سزا کرے۔(ابن القیم :۳؍۱۲۱)\nتنزیل کی اضافت اللہ کی ربوبیت کی طرف کیوں فرمائی؟\nتَنزِيلٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ ٨٠\nیقیناً یہ قرآن جو عظیم ترین صفات سے متصف ہے وہ تمام جہانوں کے رب سے ملا ہے ۔ وہ رب جو اپنے بندوں کی دنیاوی اور دینی نعمتوں کے ذریعہ پرورش کرتاہے۔اور بندوں کے حوالے سے میرے رب کی تربیت میں سے عظیم تربیت ہے نزول قرآن ۔ کہ قرآن دونوں جہاں کی مصلحتوں پر مشتمل ہے۔(السعدی :۸۳۶)\nقرآن پاک کے نزول کا تذکرہ کرنے کے بعد اللہ نے اپنی صفت ربوبیت للعالمین کا تذکرہ کیوں فرمایا ہے؟\nأَفَبِهَٰذَا ٱلۡحَدِيثِ أَنتُم مُّدۡهِنُونَ ٨١\nاے لوگو! یہ قرآن جس کی میں نے تمہیں خبر دی ، جس کی شان تم سے بیا ن کی اس قرآن کو جھٹلانے والوں سے تم میٹھی میٹھی باتیں کررہے ہو اور نرمی برت رہے ہو حالانکہ وہ اس قرآن کی تکذیب اور کفر کےمرتکب ہیں۔(الطبری :۲۳؍۱۵۲)\nاللہ کے فرمان میں (مُدْهِنُوْنَ) سے کیا مراد ہے؟\nوَتَجۡعَلُونَ رِزۡقَكُمۡ أَنَّكُمۡ تُكَذِّبُونَ ٨٢\nابن عطیہ نے کہا : مفسرین کا اجماع ہے کہ آیت بارش کے سلسلے میں یہ کہنے والوں کی بابت ہے کہ بارش فلاں اور فلاں نچھتر کے سبب نازل ہوتی ہے معنی آیت کا یہ ہے کہ تمہیں جو روزی دی جارہی ہے اس کاشکر بھی تکذیب سے کرتے ہو؟ حد ہے! (ابن جزی:۲؍۴۰۶)\nاس آیت میں رزق اور تکذیب سے کیا مرا د ہے؟\nهُوَ ٱلۡأَوَّلُ وَٱلۡأٓخِرُ وَٱلظَّٰهِرُ وَٱلۡبَاطِنُۖ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٌ ٣\n(الأول) یعنی وہ کسی ابتداء کے تصور کے بغیر ہر چیز سے پہلے ہے ۔کوئی چیز موجود نہ تھی مگر وہ موجود تھا۔اور(الآخر) یعنی کسی خاتمہ کے تصور کے بغیر وہ ہرچیز فنا ہوجانے کے بعد بھی موجود رہے گا۔چیزیں تو فنا ہوجائیں گی لیکن وہ موجود رہے گا۔ اور (الظَّاهِرُ) کا معنی ہے جو ہر چیز پر بلند اور غالب ہو۔(الباطن) کا معنی ہے ہر چیز کا عالم ۔ ابن عباس کے قول کا یہی مفہوم ہے ۔(البغوی:۴؍۳۲۲)\nان اسماء حسنیٰ کے معانی بیان کریں؟\nwords\nمَكنُونٍمستور/ محفوظ.\nمُدهِنُونَجھٹلانے والے.\nغَيرَ مَدِينِينِجزاء /حساب والے نه هوں گے.\nفَرَوحٌوسيع رحمت اور آرام.\nفَنُزُلٌضيافت.\nالأَوَّلُجس سے پهلے كوئي نه هو.\nوَالآخِرُجس كے بعد كوئي نه هو.\nوَالظَّاهِرُاور جس سے اوپر كوئي نه هو.\nوَالبَاطِنُجس سے پرے کوئی چیز نہیں."],[538,"§الحديد\ndeeds\nاللہ کے فرمان سےدو فوائد ذکر کیجئے.\nاپنے مال کا کوئی حصہ اس احسا س کے ساتھ خرچ کیجئے کہ اللہ نے آپ کو یہ جو مال عطا فرمایاہے آپ اس کے وکیل اور ذمہ دار ہیں.\nکسی مسلمان سے ایسی آیت کی شرح کیجئے جس کی اسے ضرورت بھی ہو.\nguid\nعظمت الٰہی کے ذریعہ نصیحت کرنا.\nمومن کبھی بھی اللہ کے ساتھ ہونے کے تصور سے غافل نہیں رہتا، جس کے ذریعہ اللہ اس کی خبر رکھتا ہے اور اس کی حالت کو جانتا ہے.\nجس نے اللہ کی راہ میں صدقہ کیا ہو اور اپنا مال خرچ کیا ہو وہ کیسا عظیم اجر وثواب پائے گااس چیز کا تصور کیجئے.\nrefl\nوَهُوَ مَعَكُمۡ أَيۡنَ مَا كُنتُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ ٤\nیہاں معیت (ساتھ) سے مراد علم و آگہی کی معیت ہے۔ اسی لئے اللہ نے دھمکی دی اور اعمال کے بدلے کا وعدہ فرمایا ہے اپنے اس فرمان سے: (والله بما تعملون بصير). (السعدی:۸۳۸)\nآیت میں کون سی معیت مراد ہے.\nءَامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُواْ مِمَّا جَعَلَكُم مُّسۡتَخۡلَفِينَ فِيهِۖ فَٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَأَنفَقُواْ لَهُمۡ أَجۡرٞ كَبِيرٞ ٧\n(مستخلفين فيه) کا مطلب ہے کہ آپ کے قبضے میں جو مال ہے اللہ کا ہے کیونکہ یہ مال اسی کا پیدا کردہ ہے بس یہ ہے کہ اللہ نے تمہیں اس سے فوائد اٹھانے کا حق عطا کردیا ہےاور مال میں تصرف کا اختیار دے دیا ہے گویا کہ اس بارے میں تمہاری حیثیت صرف دیکھ بھال کرنے کی ہے۔ اس لئے مال کا مالک تمہیں جہاں خرچ کا حکم دے رہا ہے وہاں خرچ کرنے سے تمہارا رکنا اور روکنا درست نہیں ہے۔(ابن جزی:۲؍۴۱۰)\n(مستخلفين فيه) ایک اہم حقیقت پر دلالت کرتی ہے اسے بیان کیجئے ؟\nوَمَا لَكُمۡ أَلَّا تُنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ\nیعنی خرچ کرو اور فقر وفاقہ کا خوف نہ کرو کیونکہ جس کی راہ میں آپ نے خرچ کیا ہے وہ زمین و آسمان کا مالک ہے اور اسی کے ہاتھ میں ان دونوں کی کنجیاں ہیں اور اسی کے پاس اس کے خزانے ہیں۔(ابن کثیر:۴؍۳۰۷)\nاللہ کا فرمان: (ولله ميراث السماوات والأرض) انفاق کا ذکر کرنے کے بعد آیا ہے اس میں کیاحکمت ہے؟\nلَا يَسۡتَوِي مِنكُم مَّنۡ أَنفَقَ مِن قَبۡلِ ٱلۡفَتۡحِ\nفتح مکہ سے پہلے خرچ کرنا زیادہ اہمیت کا حامل اس لئے ہےکہ اس وقت اسلام کے کمزور ہونے کے سبب لوگ زیادہ حاجت مند تھے اور خرچ کرنے والوں کےلئے مشقت زیادہ تھی سو اجر تکان و مشقت کے لحاظ سے ہے ۔(القرطبی:۲۰؍۲۴۰)\nفتح مکہ سے قبل انفاق عظیم کیوں ہے ؟\nمَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا فَيُضَٰعِفَهُۥ لَهُۥ وَلَهُۥٓ أَجۡرٞ كَرِيمٞ ١١\nقرآن میں جہاں بھی اس طرح قرض کا ذکر ہے(حَسَنًا)سے اس کی قید بھی آئی ہے ۔ یہ قید تین امور کی جامع ہے ۔۱۔ مال پاک ہو خراب اور بے کار نہ ہو۔۲۔ خوش دلی سے مال نکالا گیا ہواور خرچ کرتے وقت اللہ کی رضا مقصود ہو۔۳۔ اس مال کے سبب احسان جتلانے اور تکلیف پہنچانے والی کوئی بات نہ ہو ۔ پہلے امر کا تعلق مال سے ہے دوسرے کا تعلق خرچ کرنے والے اور اللہ کے درمیان سے ہے۔ تیسرے کا تعلق دینے اور لینے والے کے مابین ہے۔(ابن القیم :۳؍۱۲۸)\nصدقہ کو قرضِ حسن کب کہا جائے گا؟\nمَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا فَيُضَٰعِفَهُۥ لَهُۥ وَلَهُۥٓ أَجۡرٞ كَرِيمٞ ١١\nاس انفاق کو ‘‘قرض حسن’’ کا نام لوگوں کو ابھارنے اور خرچ کی بھر پور آمادگی کے لئے دیا گیا ہے۔ کیونکہ خرچ کرنے والے کو جب یہ معلوم ہو کہ قرض مانگنے والا ادائیگی کا اہل، وفادار اور بھلا ہے تو اس چیز سے اس کا موڈ خوشگوار ہوگا اور دل نرم ہوجائے گا۔(ابن القیم :۳؍۱۲۸)\nانفاق فی سبیل اللہ کو قرض حسن کا نام کیوں دیا گیا؟\nمَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا فَيُضَٰعِفَهُۥ لَهُۥ وَلَهُۥٓ أَجۡرٞ كَرِيمٞ ١١\nقشیری رحمہ اللہ فرماتے ہیں: قرض حسن کا مطلب ہے : صدقہ کرنے والا سچی نیت رکھتا ہو، بہ خوشی دے رہا ہو اس کی رضامقصود ہو دکھاوا ا ور نمائش کی بات نہ ہو اور مال حلال ہو۔(القرطبی:۲۰؍۲۴۴)\nقرض حسن کیا ہے؟\nwords\nمَا يَلِجُجو داخل هوتا هے (بارش وغيرع ).\nوَمَا يَعرُجُ فِيهَااور جو چڑھتا هے (فرشتے اور اعمال ).\nيُولِجُوه داخل كرتا هے.\nمِمَّا جَعَلَكُم مُستَخلَفِينَ فِيهِوه مال جس ميں الله تعاليٰ نے تمهيں تصرف كے ليے جانشين بنايا.\nالفَتحِفتح مكه.\nالحُسنَىجنت.\nقَرضًا حَسَنًاالله سے بدله كي اميد پر خرچ / جس ميں نه تكليف هو نه امتحان."],[539,"§الحديد\ndeeds\nیہ دعا پڑھیں: ‘‘اَللّٰهُمَّ يَا مُقَلِّبَ الْقُلُوبِ، ثَبِّتْ قَلْبِيْ عَلٰى دِيْنِكَ’’‘‘یا اللہ ! اے دلوں کو پلٹنے والے میرے دل کو اپنے دین پر ثابت قدم رکھ‘‘.\nقرآن کریم سے کوئی ایک صفحہ دھیان سے پڑھئے اور دوفوائد کا استخراج کیجئے.\nکوئی ایسا صدقہ کیجئے، روزقیامت جس کا کئی گنا ملنے کی امید رکھ سکیں.\nguid\nبندے کو روز قیامت اس کے عمل کے اعتبار سے روشنی عطا کی جائے گی.\nدین میں شک و شبہ سے بچئے کیونکہ وہ نفاق کی علامت میں سے ہے.\nبےکار کی آرزؤں سے سے دور ہو یہ مفلسوں کا بنیادی مال ہے.\nrefl\nيَوۡمَ تَرَى ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ يَسۡعَىٰ نُورُهُم بَيۡنَ أَيۡدِيهِمۡ\nعبد اللہ بن مسعود رضی اللہ عنہ نے فرمایا: انہیں روشنی ان کے عمل کے حساب سے ملے گی ان میں بعض وہ ہوں گے جن کو کھجور کے درخت جتنی بڑی روشنی ملے گی اور ان میں سے بعض کی روشنی کھڑے آدمی کے برابر ہوگی۔ ان میں سب سے کم روشنی اس کی ہوگی جسے انگوٹھے کے چھور کے برابر روشنی ملے گی ۔ وہ بھی کبھی بجھ جائے گی اور کبھی جل پڑے گی۔(البغوی:۴؍۳۲۴)\nکیا روز قیامت مومنوں کی روشنی مختلف ہوگی ؟اور یہ روشنی کس بنا پر مختلف ہوگی؟\nيَوۡمَ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلۡمُنَٰفِقَٰتُ لِلَّذِينَ ءَامَنُواْ ٱنظُرُونَا نَقۡتَبِسۡ مِن نُّورِكُمۡ قِيلَ ٱرۡجِعُواْ وَرَآءَكُمۡ فَٱلۡتَمِسُواْ نُورٗاۖ\nحسرت و افسوس کے سبب یہ چیز بہت گراں گزرے گی کہ بندہ کامیابی و کامرانی کے راستے پر جا لگے تاآنکہ اسے یقین سا ہونے لگے کہ اسے نجات مل جائے گی وہ نیک بختوں کے منازل دیکھنے لگے(اقتطع عليهم)ان پر بدبختی مسلط کردی جائے گی ۔ اللہ کی پناہ ہو اس کی غضب اور اس کے عقاب سے ۔(ابن القیم :۳؍۱۲۹)\nآیت کی روشنی میں روز قیامت کو منافقین پر ہونے والےنفسیاتی عذاب کا تذکرہ کیجئے؟\nيُنَادُونَهُمۡ أَلَمۡ نَكُن مَّعَكُمۡۖ قَالُواْ بَلَىٰ وَلَٰكِنَّكُمۡ فَتَنتُمۡ أَنفُسَكُمۡ وَتَرَبَّصۡتُمۡ وَٱرۡتَبۡتُمۡ وَغَرَّتۡكُمُ ٱلۡأَمَانِيُّ حَتَّىٰ جَآءَ أَمۡرُ ٱللَّهِ وَغَرَّكُم بِٱللَّهِ ٱلۡغَرُورُ ١٤\nان کے حق میں بربادی کے چار اسباب بیان فرمائے: ان کےنفس کا فتنہ ، مومنوں کی گھات میں رہنا، رسول کی صداقت میں شبہ کرنا، نفس کی رنگی ہوئی خواہشات سے دکھوکے کھانا ۔(ابن عاشور:۲۷؍۳۸۵)\nآیت میں ذکر کردہ بربادی کے اسباب بتائیں؟\n۞أَلَمۡ يَأۡنِ لِلَّذِينَ ءَامَنُوٓاْ أَن تَخۡشَعَ قُلُوبُهُمۡ لِذِكۡرِ ٱللَّهِ\n(أن تخشع) یعنی کیا وہ وقت نہیں آیا کہ وہ ایمان کا بلند مرتبہ حاصل کرلیں۔ بلند مرتبہ کے حصول کا مطلب ہے دل نرم ہوجائیں، دلوں میں جھکاؤ اور خضوع ہو، اطمینان ہو، تسلیم و رضا ہو، ختم ہونے والی چیزوں سے دل اعراض کرے اور باقی رہنے والی چیزوں پر توجہ کرے۔(قلوبهم لذكر الله) یعنی اس عظیم ترین بادشاہ اللہ کے لئے، ہر بھلائی اسی کی طرف سے ہے ۔ چنانچہ دل جھکنے کے سبب وہ جو ایمان میں سچا نہ تھا سچا ہو جاتا، دین کے حوالے سے جو کمزور تھا قوی ہوجاتا سو اپنے دین کی خرابی کے لئے دو ااور دل کی بیماری کے لئے شفا وہ قرآن کے سوا کہیں نہ ڈھونڈتا کیونکہ اللہ کا ذکر دلوں کی پیاس دور کرتا اور اس کے آئینے صاف کردیتا ہے۔(البقاعی:۱۹؍۲۷۹)\nدل کی سختی کی کامیاب دوا کیا ہے؟\nوَلَا يَكُونُواْ كَٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلُ فَطَالَ عَلَيۡهِمُ ٱلۡأَمَدُ فَقَسَتۡ قُلُوبُهُمۡۖ\n(فقست) یعنی مدت لمبی ہونے کےسبب سختی پیدا ہوگئی (قلوبهم) یعنی دل ایسے سخت اور اتنے کج ہوگئے کہ ان میں اطاعت کے امور اور بھلائی کے لئے جگہ ہی نہ رہی۔قشیری رحمہ اللہ فرماتے ہیں : دل کی سختی خواہشات کی اتباع سے آتی ہے اور شہوت کے ساتھ دل کی صفائی اکٹھا نہیں ہوسکتی ۔(البقاعی:۱۹؍۲۸۰)\nدل کی سختی کا کیا معنی ہے؟\nوَلَا يَكُونُواْ كَٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلُ فَطَالَ عَلَيۡهِمُ ٱلۡأَمَدُ فَقَسَتۡ قُلُوبُهُمۡۖ وَكَثِيرٞ مِّنۡهُمۡ فَٰسِقُونَ ١٦\nدل کی سختی برائیوں کا مرکز ہے اور سختی اللہ سے لمبے عرصے تک غافل رہنے سے پیدا ہوتی ہے ۔(آلوسی:۱۴؍۱۸۱)\nانسان پر دل کی سختی کے خطرات بیان فرمائیں؟\nٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يُحۡيِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ قَدۡ بَيَّنَّا لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَعۡقِلُونَ ١٧\nآیت میں ایمان والے دلوں کو ذکراللہ کی جس انداز میں حاجت ہوتی ہےاس کی تمثیل مردہ زمین کی بارش کی ضرورت سے دی گئی ہے ۔ اور ذکر سے دلوں کی صفائی و روشنی کی حالت کی تمثیل بنجر زمین کو بارش سے ہرا بھرا کردینے سے بیان کی گئی ہے ۔(ابن عاشور:۲۷؍۳۹۳)\nاللہ زمین کو اس کی موت کے بعد زندہ کرتا ہےاس بات کی خبر دینے میں کیا فائدہ ہے ؟\nwords\nنَقتَبِسهم ليتے هيں / هم حاصل كرتے هيں.\nوَتَرَبَّصتُماور تم انتظار ميں رهے(كه رسول صلی اللہ علیہ وسلم پر اورمومنين پر پريشانياں آئيں).\nوَغَرَّتكُمُ الأَمَانِيُّتمهيں دھوكے ميں ركھا اميدوں نے.\nفِديَةٌوه عوض جو الله تعاليٰ كے عذاب سے بچنے كے ليے ديا جائے.\nمَأوَاكُمُتمهارا ٹھكانا.\nأَلَم يَأنِكيا وه وقت نهيں آيا."],[540,"§الحديد\ndeeds\nدعا کیجئے کہ اے اللہ مجھے صدیقین(نہایت سچے لوگوں) کے مقام تک پہنچا.\nاللہ سے دعا کیجئے کہ آپ کو دنیا سے بے رغبتی عطا فرمائے.\nآج تمام نماز وں میں جلدی کیجئے تاکہ پہلی صف میں امام کے پیچھے رہیں.\nguid\nیہ جان لیں کہ جنت اللہ کا فضل ہے وہ اسے اپنے بندوں میں سے جس کو چاہتا ہے دیتا ہے.\nخاکسار نرم دل اور قریب رہنے والا بنئے، اللہ تعالیٰ گھمنڈی اور غرور کرنے والوں کو پسند نہیں کرتا.\nیہ جان لیں کہ اللہ اپنے بندوں سے بے نیاز ہے (یعنی ان کا محتاج نہیں) وہ ہر اعتبار سے قابل تعریف ہے، کسی تعریف کرنے والے کی تعریف کا محتاج نہیں.\nrefl\nٱعۡلَمُوٓاْ أَنَّمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا لَعِبٞ وَلَهۡوٞ وَزِينَةٞ وَتَفَاخُرُۢ بَيۡنَكُمۡ وَتَكَاثُرٞ فِي ٱلۡأَمۡوَٰلِ وَٱلۡأَوۡلَٰدِۖ\nاوردنیا داروں کے یہاں واقعی یہ چیز موجود ہے ۔ اس کے بر خلاف جنہیں دنیا اور اس کی حقیقت کی معرفت ہے وہ دنیا کو صرف ایک گزرگاہ سمجھتے ہیں ہمیشہ رہنے کی جگہ نہیں سو انہوں نے اللہ سے قریب کرنے والی چیزوں میں آگے بڑھنے کی کوشش کی اور ان وسائل کو اختیار کیا جو انہیں اللہ تک پہنچا سکیں۔(السعدی:۸۴۱)\nجب آپ دنیا کی حالت جان گئے تو آپ کا دنیاکی بابت کیا موقف ہوناچاہئے ؟\nٱعۡلَمُوٓاْ أَنَّمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا لَعِبٞ وَلَهۡوٞ وَزِينَةٞ وَتَفَاخُرُۢ بَيۡنَكُمۡ وَتَكَاثُرٞ فِي ٱلۡأَمۡوَٰلِ وَٱلۡأَوۡلَٰدِۖ\nآیت میں لوگوں کی زندگی کے مراحل بھی بیان کئے گئے ہیں کہ ہر کوئی کس طرح مرحلہ وار ترقی کرتا ہے :تو کھیل بچپن اورلڑکپن کا مرحلہ ہے۔لہو نوخیزی کا مرحلہ ہے ، زینت پختہ جوانی کا مرحلہ ہے اور فخر کرنا ادھیڑعمر کا مرحلہ ہے اور زیادہ سے زیادہ مال جمع کرنا بڑھاپے کامرحلہ ہے۔(ابن عاشور:۲۷؍۴۰۱)\nآیت میں لوگوں کے مراحل کا ذکر ہے اسے بیان کیجئے ؟\nوَفِي ٱلۡأٓخِرَةِ عَذَابٞ شَدِيدٞ وَمَغۡفِرَةٞ مِّنَ ٱللَّهِ وَرِضۡوَٰنٞۚ\nآخرت کی صورت حال میں دوباتوں میں سے ایک بات ضرورہوگی یا جہنم کا سخت عذاب ہوگا ۔یا اللہ کی طرف سے گناہوں کی مغفرت ، سزاؤں کی منسوخی اور اللہ کی خوشنودی اس کو حاصل ہوتی ہے جس کو دار رضوان مل گیا ۔ یہ تمام چیزیں دنیا سے بے رغبت کرتی ہیں اور آخرت کا شوق دلاتی ہیں۔(السعدی:۸۴۱)\nیہ جاننے کے بعد کہ آخرت یا توعذاب کانام ہے یا مغفرت کا ،دنیا کے تعلق سے آپ کا کیا نقطۂ نظر ہے ؟\nوَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا مَتَٰعُ ٱلۡغُرُورِ ٢٠\nسعید بن جبیر فرماتے ہیں (دنیا) دھوکے کا سامان اس کے لئے ہے جو دنیا کے اندر آخرت کی طلب میں مشغول نہیں رہا لیکن جو آخرت کی طلب میں دنیا میں مشغول رہا اس کے لئے یہ مصروفیت اس سے بہترین چیز تک پہچانے کا سامان ہے ۔(البغوی:۴؍۳۲۸)\nکیا دنیا ساری مخلوق کے لئے دھوکے کا سامان ہے؟\nلِّكَيۡلَا تَأۡسَوۡاْ عَلَىٰ مَا فَاتَكُمۡ وَلَا تَفۡرَحُواْ بِمَآ ءَاتَىٰكُمۡۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ مُخۡتَالٖ فَخُورٍ ٢٣\nیعنی ہم نے تمہیں صاف بتا دیا کہ چیزیں مخلوق کے وجود سے پہلے ہی طے شدہ اور لکھی ہوئی ہیں اور جو کچھ لکھا ہوا ہے وہ ہوکے رہے گا یہ بات اس لئے بتا دیا کہ اگر کوئی چیز کھو جائے تو تمہیں اس کا غم نہ ہو کیونکہ کھو نا طے تھا اور اس لئے کہ جس چیز کی امید نہیں ہوتی اس پر تکلیف بھی کم ہوتی ہے ۔ اوراس لئے بھی بتا دیا تاکہ جو کچھ تمہیں ملا ہے اس پر ایسا نہ ہو کہ پھولے نہ سماؤکیونکہ جب تمہیں یہ یقین رہے گا کہ جو بھی رزق اور بھلائی مقدر ہے مل کے رہے گی تو تمہاری خوشی کم ہوجائے گی ۔(الشنقیطی:۲۷؍۵۴۹)\nمخلوق کے وجود سے قبل چیزیں لکھی ہوئی تھیں یہ جاننے سے کیا فائدہ ہے اس کی وضاحت کیجئے ؟\nلِّكَيۡلَا تَأۡسَوۡاْ عَلَىٰ مَا فَاتَكُمۡ وَلَا تَفۡرَحُواْ بِمَآ ءَاتَىٰكُمۡۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ مُخۡتَالٖ فَخُورٍ ٢٣\nاگر یہ اعتراض کیا جائے کہ بھلی چیز پر خوشی اور بری چیز پر غم انسان کے بس میں نہیں ہے کہ اسے کنٹرول کرے۔ جیسا کہ ابو بکر صدیق رضی اللہ عنہ کے پاس بہت سارا مال آیا تو آپ نے فرمایاالٰہی جو تونے ہمیں یہ زینت دنیا عطا فرمائی ہے اس کی خوشی کو ضبط کرنے کی ہم میں طاقت نہیں ہے۔ اس کا جواب یہ ہے کہ آیت میں خوشی سے روکنے سے مراد وہ خوشی ہے جو کبر اور سرکشی تک پہنچائے اور غم سے مراد وہ غم ہے جس سے آدمی صبر و تسلیم سے باہر ہوجائے۔(ابن جزی:۲؍۴۱۵)\nکچھ کھو جائے تو اس پر غم اور کچھ ملے تو اس پر خوشی سے آیت میں روکا گیا ہے ۔ بتائیے کہ روکنے سے کیا مقصود ہے؟\nوَٱللَّهُ لَا يُحِبُّ كُلَّ مُخۡتَالٖ فَخُورٍ ٢٣ ٱلَّذِينَ يَبۡخَلُونَ وَيَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبُخۡلِۗ\nدین و دنیا کے لئے جو بھی چیز مفید ہو علم، مال وغیرہ بخل سب کو شامل ہے علم کا بخیل وہ ہے جو اسے روکے۔ مختال وہ ہے جو اکڑ کے سبب اسے طلب ہی نہ کرے یا اکڑ کے سبب اسےخرچ نہ کرےاور ایسابہت ہوتا ہے ۔ اس کے برعکس طلب علم میں تواضع ہے اور علم بانٹنے میں سخاوت کا مظاہر ہ ہے ۔(ابن تیمیہ:۶؍۲۱۷)\nبخیلی غیر محسوس طریقے سے بہت سے لوگوں میں پائی جاتی ہے اس کی وضاحت کریں؟\nwords\nالصِّدِّيقُونَتصديق ميں مبالغه كرنے والے.\nوَالشُّهَدَاءُجو الله كي راه ميں قتل كئے گئے هوں.\nالكُفَّارَكاشتكار۔ انهيں يه نام اس ليے دياگيا هے كه وه دانے مٹي ميں چھپاتے هيں.\nيَهِيجُوه خشك هو جاتا هے.\nحُطَامًاچورا / ريزه ريزه.\nنَبرَأَهَاهم ان مخلوقات كو پيدا كريں.\nتَأسَواتم غم نه كھاؤ."],[541,"§الحديد\ndeeds\nاپنے ارد گرد اللہ تعالیٰ کی طاقت کے جو مظاہر آپ دیکھ رہے ہیں ان میں سے تین مظاہر کو شمار کرائیں.\nاللہ سے دعا کیجئے کہ اس دین کی مدد فرمائے.\nاس دین کی نصرت کے لئے کسی خیری عمل کے لئے چندہ دیجئے.\nguid\nآسمان وزمین عدل ہی سے قائم ہیں سو اپنے تمام معاملات میں عدل کے حریص بنئے.\nکوئی بھی کام آپ کرتے ہیں یا دین کی نصرت میں کوئی بات بولتے ہیں تو وہ اللہ کے یہاں آپ کے حساب میں لکھ دی جاتی ہے.\nخیر و بھلائی کے خزانے صرف اللہ کے ہاتھ میں ہیں.\nrefl\nلَقَدۡ أَرۡسَلۡنَا رُسُلَنَا بِٱلۡبَيِّنَٰتِ وَأَنزَلۡنَا مَعَهُمُ ٱلۡكِتَٰبَ وَٱلۡمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلۡقِسۡطِۖ وَأَنزَلۡنَا ٱلۡحَدِيدَ فِيهِ بَأۡسٞ شَدِيدٞ وَمَنَٰفِعُ لِلنَّاسِ\nاقامت دین کی بنیاد دو باتو ں پر ہے ایک بات تو وہ ہے جو اللہ کے فرمان (وأنزلنا معهم الكتاب والميزان)؛میں مذکور ہے کیونکہ اس میں حق کی بنیاد پر دلائل کا اثبات ہے۔اور آیت حجت کو بیان کرتی اور امر و نہی اور ثواب و عقاب کی وضاحت کرتی ہے ۔لیکن جب کفار نے اس وضاحت و بیان کے باوجود اپنے کفر اور رسولوں کی تکذیب پر ضدکامظاہرہ کیا تب اللہ نے لوہا نازل فرمایا نازل کرنے کا مطلب یہ ہے کہ نبی نوع انسان کے لئے پیدا فرمایا تاکہ یہ مومنین کے لئے کفار و معاندین کو ڈرا نے کا سامان ہو مرادانہیں تلواروں، نیزوں اورتیروں سے قتل کرناہے۔(الشنقیطی: ۷؍۵۴۹)\nدین اسلام کے قائم کرنے کی بنیاد دوچیزوں پر ہے وہ چیزیں کیا ہیں؟\nلَقَدۡ أَرۡسَلۡنَا رُسُلَنَا بِٱلۡبَيِّنَٰتِ وَأَنزَلۡنَا مَعَهُمُ ٱلۡكِتَٰبَ وَٱلۡمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلۡقِسۡطِۖ وَأَنزَلۡنَا ٱلۡحَدِيدَ فِيهِ بَأۡسٞ شَدِيدٞ وَمَنَٰفِعُ لِلنَّاسِ\nیعنی ہمارے حجت قائم کرنے کے بعد بھی جس نے حق کا انکارکیا اس سے عناد برتا اس کی تنبیہ کےلئے ہم نےلوہا پیدا کیا۔ یہی وجہ ہے کہ رسول صلی اللہ علیہ وسلم نبوت کے بعد مکہ میں تیرہ سال تک رہے آپ پرمکی سورتوں کی وحی ہوتی رہی اور تمام سورتوں میں مشرکین سے مباحثۂتوحید کی وضاحت و بیان اور اس کی رہنمائیاں ہوتی تھیں پھر جب مخالفین شریعت پرحجت قائم ہوچکی تو اللہ نے ہجرت کاحکم فرمایا اور انہیں قرآن کو جھٹلانے والوں، اس کی مخالفت کرنے والوں سے قتال کااور سر اور گردن مارنے کاحکم دیا ۔(ابن کثیر: ۴؍۳۱۵)\nاللہ نے انزال کتب کو انزال حدید پر کیوں مقدم فرمایا؟\nوَلِيَعۡلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ بِٱلۡغَيۡبِۚ إِنَّ ٱللَّهَ قَوِيٌّ عَزِيزٞ ٢٥\nلوگوں کی طرف سے اللہ کی مددکرنےکا مطلب اللہ کے دین کی مددہے ورنہ اللہ مدد سے بے نیاز ہے۔اللہ کی مدد پر(ورسله) کابھی عطف ہے اس کا مطلب ہے دین کو قائم کرنے والوں کی مدد!اس مدد میں رسول کے بعد ان کے شرائع کی مدد بھی شامل ہے ۔(ابن عاشور:۲۷؍۴۱۸)\nآیت میں اللہ اور اس کے رسولوں کی مدد سے کیا مقصود ہے؟\nوَجَعَلۡنَا فِي قُلُوبِ ٱلَّذِينَ ٱتَّبَعُوهُ رَأۡفَةٗ وَرَحۡمَةٗۚ\nنصاریٰ دوسروں کے مقابلے میں اس وقت نرم دل تھے جب وہ عیسیٰ کی شریعت پر کاربند تھے ۔(السعدی:۸۴۳)\nنصاریٰ مومنین کے حوالے سے دل کے اعتبار سے کب نرم تھے؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَءَامِنُواْ بِرَسُولِهِۦ يُؤۡتِكُمۡ كِفۡلَيۡنِ مِن رَّحۡمَتِهِ\nیعنی اس کی سزا سےڈرو چنانچہ اپنے اور اللہ کی ناراضگی کے مابین کہ وہی بادشاہ اعظم ہے اس کے ساتھ ادب کے ذریعہ حفاظت کا سامان کرو۔اور ان کی تدبیر سے غافل نہ رہو سو چوکنا رہو کہ اللہ نے تمہیں جو دیا ہے وہ چھین نہ لے لہٰذا رسول کی اتباع کرو اور سپردگی کامظاہرہ کرو اور آپ کے متبعین کی حفاظت کرو تاکہ تم ہلاک نہ ہو۔(البقاعی:۱۹؍۳۲۴)\nجو تقویٰ اور خوف الٰہی سے خالی ہو اس کی کیا سزا ہے ؟\nوَيَجۡعَل لَّكُمۡ نُورٗا تَمۡشُونَ بِهِ\nیعنی بیان وہدایت : ابن عباس کے بقول اس سے مراد قرآن ہے ۔یہ بھی کہاگیا ہےکہ مرادوہ روشنی ہےجس کی مدد سے آخرت میں پل صراط پر چلو گے ۔ یہ بھی قول ہےکہ وہ (معنوی) روشنی مراد ہے جس سے تم لوگوں کو اسلام کی دعوت دیتے ہو سو تم دین اسلام میں سردار ہوجاؤ گے۔ تم سے وہ ریاست ختم نہیں کی جائے گی،جس میں تم تھے۔ یہ بات اس لئے کہی جارہی ہے کہ وہ لوگ ڈرتے تھے کہ محمد پر ایمان لانے سے ان کی سرداری چلے جائے گی۔(القرطبی :۲۰؍۲۷۸)\nوہ کون سا نور ہوگا جو اللہ ان لوگوں کو عطا کرے گا.\nوَٱللَّهُ غَفُورٞ رَّحِيمٞ ٢٨\nیعنی اللہ اس کا ایسامالک ہے کہ اس کی ملکیت اس سے جدا نہیں ہو سکتی ۔اس کے ساتھ اس میں کسی کی بادشاہت نہیں ہوگی اور قطعاً کسی بھی طرح کا تصرف نہ ہوگا اس لئے وہ جس کو جو چاہتا ہےخصوصیت عطا کرتا ہے کسی طور پر اس پر کوئی کسی اعتراض کی طاقت نہیں رکھتا۔(البقاعی:۱۹؍۳۳۰)\nاللہ تعالیٰ کی اس صفت میں کہ وہ صاحب فضل عظیم ہے کیا رہنمائی ہے؟\nwords\nبِالبَيِّنَاتِواضح دلائل.\nوَالمِيزَانَترازو/ عادلانه اقوال و أفعال.\nبَأسٌقوت.\nعَزِيزٌغالب / جو كبھي مغلوب نه هو.\nقَفَّينَا عَلَى آثَارِهِمهم نے ان كا پيچھا كيا؛ ان كے بعد نبي بھيجے.\nوَرَهبَانِيَّةًرهبانيت؛ تعبد ميں غلو.\nمَا كَتَبنَاهَاهم نے اس كو فرض نهيں كيا تھا.\nفَمَا رَعَوهَااسے اس طرح قائم نهيں كيا۔ بلكه بدل ڈالا.\nكِفلَينِدو گنا."],[542,"§المجادلۃ\ndeeds\nاللہ تعالیٰ کے سامنے اس دعاء کےساتھ آہ وزاری کیجئے:“اَللّٰهُمَّ اِنِّيْ اَشْكُوْ اِلَيْكَ ضَعْفَ قُوَّتِيْ، وَقِلَّةَ حِيلَتِيْ، وَهَوَانِيْ عَلَى النَّاسِ” ‘‘اے اللہ میں تیرے سامنے اپنی طاقت کی کمزوری،اپنی تدبیر کی کمی، اور لوگوں کے سامنے اپنی ذلت ورسوائی کی شکایت کرتاہوں”.\nكسى کمزور، غریب یا مظلوم عورت پر صدقہ کیجئے یا اس كى مدد کیجئے.\nاپنا وہ گناہ یاد کیجئے جسے آپ نے کیاہے، اور اللہ تعالىٰ سے اسکی بخشش طلب کیجئے.\nguid\nاللہ تعالىٰ کا علم بے انتہا وسیع ہے،وہ ہر شئی کو محیط ہے اور ہر آواز سنتا ہے.\nخبردار، اللہ کے حدود سے آگے مت بڑھئے.\nہراس عمل سےمتنبہ رہئےجوقیامت کےدن آپ کے لئے ضرررساں ہو، کیونکہ آپ کا ہر کام گناجاتا ہے، خواہ اچھا ہو یا برا ، اللہ نےاسے شمار کرکھا ہے.\nrefl\nإِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٌ ١\nاس میں اللہ تعالىٰ کی سماعت و بصارت کا کمال اور ہر چھوٹے و بڑے معاملہ میں ان کے احاطہ کی خبر ہے۔اور اس میں اس بات کا اشارہ ہے کہ اللہ تعالیٰ عنقریب اس کی شکایت کو دور کردیگا، اور اس کی پریشانی ختم کردیگا۔ (السعدی:۸۴۴)\nیہ آیت کیوں ختم کی گئی ان دونوں مقدس نام کے ساتھ؟\nٱلَّذِينَ يُظَٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَٰتِهِمۡۖ إِنۡ أُمَّهَٰتُهُمۡ إِلَّا ٱلَّٰٓـِٔي وَلَدۡنَهُمۡۚ وَإِنَّهُمۡ لَيَقُولُونَ مُنكَرٗا مِّنَ ٱلۡقَوۡلِ وَزُورٗاۚ وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٞ ٢\nان آیات سے یہ بات معلوم ہوتی ہے کہ ظہار کرنا حرام ہے، بلکہ علماء کہتے ہیں کہ یہ گناہ کبیرہ ہے؛کیونکہ اس میں اللہ تعالیٰ کی اجازت کے بغیر اس کے حکم کے رد وبدل کی طرف ایک اقدام ہے، اور یہ بہت سارے گناہ کبیرہ سے زیادہ خطرناک ہے۔ (الألوسی:۱۴؍۲۰۰)\nظہار کو زور ومنکر سے متصف کرنے کی کیا وجہ ہے؟\nوَإِنَّهُمۡ لَيَقُولُونَ مُنكَرٗا مِّنَ ٱلۡقَوۡلِ وَزُورٗاۚ\nظہار کے منکر اور زور ہونے میں فرق یہ ہیکہ ان کا یہ قول: (اَنْتِ عَلَيَّ كَظَهْرِ اُمِّيْ) (تو مجھ پر میری ماں کی پشت کی طرح ہے) دوباتوں(خبر و انشاء) پر مشتمل ہے: یعنی شوہر کا بیوی کے بارے میں اس طرح کے جملے سے خبر دینا ، اور اپنی طرف سے اسے حرام قرار دینا، اس طرح یہ جملہ اخبار وانشاء دونوں پر مشتمل ہے، چنانچہ یہ خبر جھوٹی ہے، اور انشاء (حرام ٹھہرانا) منکر ہے۔كیونکہ زور اس باطل كو کہتے ہیں ہے جو ثابت شدہ حق کے خلاف ہوتا ہے، اور منکر وہ ہے جو معروف کے بر خلاف ہے۔(ابن قیم: ۳؍۱۳۹)\nظہار کو منکرو زور سے کیوں متصف کیا گیا؟\nذَٰلِكَ لِتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِه\nیہ حکم جس کو ہم نے تم سے بیان کیا یہ اس لئے کہ تم اللہ کی اور اس کے رسول کی حکم برداری کرو، اور یہ اس حکم ، اور دیگر احکام کی پابندی کے ذریعہ ممکن ہے؛ کیونکہ اللہ تعالیٰ کے احکام کی پابندی، اور اس پر عمل ایمان کا حصہ ہے، بلکہ یہی مطلوب ہے، اور اس سے ایمان بڑھتا ہے، اور کامل ہوتا ہے۔ (السعدی:۸۴۴)\nنیک عمل اور ایمان کے ما بین کیا تعلق ہے، اس آیت کی روشنی میں بیان کیجئے.\nإِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُواْ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ\nیعنی: وہ ہو ہلاک کئے جائیں گے۔ اور قتادہ نے کہا: وہ پہلے لوگوں کی طرح ذلیل کئے جائیں گے ، اور کہا گیا: وہ عذاب دیئے جائیں گے، اور یہ بھی کہا گیا کہ: خندق کے دن وہ غیظ و غضب میں مبتلا کئے گئے، اور یہ بھی کہا گیا: عنقریب وہ ذلیل کئے جائیں گے، اللہ تعالیٰ کی طرف سے یہ بشارت ہے کہ وہ مومنوں کی مدد فرمائے گا۔(القرطبی: ۲۰؍۳۰۵)\nاللہ تعالیٰ کے قول: (كبتوا) سے کیا مراد ہے؟ اور اس آیت کے اندر کون سی بشارت ہے؟۔\nإِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُواْ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ وَقَدۡ أَنزَلۡنَآ ءَايَٰتِۢ بَيِّنَٰتٖۚ وَلِلۡكَٰفِرِينَ عَذَابٞ مُّهِينٞ ٥\nیہ بات ثابت ہو گئی کہ اللہ اور اس کے رسول کی مخالفت کرنے والے ذلیل وخوار ہوتے ہیں برباد ہوتے ہیں ، بغض وحسد سے بھرے ہوتے ہیں۔ اور یہ اس وقت ہوتا ہے جب اسے ڈر ہوکہ اگرکھل کر مخالفت کرےگا تو وہ قتل کر دیاجائے گا، البتہ جس کے لئے کھل کر مخالفت کرنا ممکن ہو، اور اس کا خون ومال محفوظ ومامون ہو تووہ ذلت و رسوائی محسوس نہیں کرتا ہے بلکہ خوش و مطمئن ہوتا ہے، اور اس لئے بھی کہ اللہ تعالیٰ نے فرمایا: (كبتوا كما كبت الذين من قبلهم) ان سے قبل جن لوگوں نے بھی رسولوں کی مخالفت کی، بطور خاص رسول اللہ صلی اللہ علیہ وسلم کی، تو اللہ تعالیٰ نے انہیں اس طرح ذلیل کیا کہ انہیں اپنی طرف سے بھیجے گئے عذاب سے ہلاک کر دیا، یا مومنوں کے ہاتھوں انہیں تباہ و برباد کردیا۔ (ابن تیمیہ: ۶؍۲۴۰)\nاللہ تعالىٰ اور اس کے رسول کی مخالفت سے انسان اس دنیا میں دل کا مریض ہوجاتا ہے، اور آخرت میں عذا ب الہٰی کا مستحق ٹھہرتا ہے۔ اس کا مفہوم واضح کیجئے.\nيَوۡمَ يَبۡعَثُهُمُ ٱللَّهُ جَمِيعٗا فَيُنَبِّئُهُم بِمَا عَمِلُوٓاْۚ أَحۡصَىٰهُ ٱللَّهُ وَنَسُوهُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ ٦\n(أحصاه الله ونسوه) مستقل جملہ ہے جو مقدر سوال کا جواب ہے، گویا کہ سوال کیا گیا: اللہ تعالیٰ کیسے انہیں ان کے اعمال بتا سکتا ہے؟ وہ تو بہت زیادہ ہیں، اور بہت طرح کے ہیں؟تو جوابا کہا گیا:اللہ تعالیٰ نے ان کے تمام اعمال کو شمار کر رکھا ہے، کوئی ایک چیز بھی نہیں چھوٹی ہے اگر چہ یہ لوگ بھول گئے ہیں انہیں یاد نہیں ہے، لیکن یہ لوگ اپنے نامہ اعمال میں سب لکھا ہوا پائیں گے۔(الشوکانی: ۵؍۱۸۶)\nیہاں ایک سوال پوشیدہ ہے جس کا جواب اللہ تعالیٰ کا قول: (أحصاه الله ونسوه) ہے،بتائیے وہ سوال کیا ہے؟\nwords\nتُجَادِلُكَوه آپ سے بار بار رجوع كر رهي تھي(خوله بنت ثعلبه ).\nزَوجِهَااپنے شوهر كے بارے ميں (اوس بن الصامت ).\nوَزُورًاجھوٹ بولتے هوئے.\nفَتَحرِيرُ رَقَبَةٍايك غلام كو آزاد كرنا(يا باندي كو ؛ اور وه مؤمن بھي هو ).\nيَتَمَآسَّاوه جماع كريں.\nيُحَآدُّونَوه نافرماني كرتے هيں ؛ مخالفت كرتے هيں.\nكُبِتُواوه بے يارو مددگار رهے؛ اور ذليل كئے گئے."],[543,"§المجادلۃ\ndeeds\nکسی مسلمان کے ساتھ بیٹھو اور کسی ایسے موضوع پر گفتگو کرو جس سےتمہارے ایمان میں اضافہ ہو، اور نیکی و پرہیزگاری کی باتوں پر سرگوشی کرو.\nمومنوں کے متعلق حسن ظن رکھو؛ کیونکہ سرگوشی بدگمانی کی وجہ سے ہوتی ہے.\nدروس، حلقے، اور عام مجالس میں جب بیٹھو تو اپنے بھائی کے لئے کشادگی پیدا کرو، اللہ تعالیٰ تمہارے لئے بھی کشادگی پیدا کریگا.\nguid\nاللہ تعالىٰ کے علم کی وسعت کویاد رکھو،اور جان لو کہ کوئی چیز اس سے چھپنے والی نہیں ہے.\nجب تمہیں غم لا حق ہو تو جان لو کہ یہ شیطان کی طرف سے ہے؛ کیونکہ اس کی ہمیشہ كوشش رہتی ہے کہ تمہیں حزن وملال میں مبتلا کرے.\nحزن وملال دور کرنے کا طریقہ یہ ہے کہ اللہ تعالیٰ پر بھروسہ کیا جائے.\nrefl\nأَلَمۡ تَرَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ مَا يَكُونُ مِن نَّجۡوَىٰ ثَلَٰثَةٍ إِلَّا هُوَ رَابِعُهُمۡ وَلَا خَمۡسَةٍ إِلَّا هُوَ سَادِسُهُمۡ وَلَآ أَدۡنَىٰ مِن ذَٰلِكَ وَلَآ أَكۡثَرَ إِلَّا هُوَ مَعَهُمۡ أَيۡنَ مَا كَانُواْۖ ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُواْ يَوۡمَ ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ ٧\nاللہ تعالىٰ نے کلام کی ابتداء علم سے کی ہے، اور انتہا بھی علم سے؛اسی لئے ابن عباس رضی اللہ عنہما، ضحاک، سفیان ثوری، اور احمد بن حنبل رحمہم اللہ جمیعانے فرمایا: اللہ ان (بندوں) کے ساتھ ہے اپنے علم کے ذریعے۔(ابن تیمیہ: ۶؍۲۴۱)\nآپ اس آیت سے کیسے استدلال کریں گے کہ اللہ تعالیٰ کاقول: (هُوَ مَعَهُمْ) میں معیت سے مراد معیت بالعلم ہے، معیت بالذات نہیں ؟\nوَإِذَا جَآءُوكَ حَيَّوۡكَ بِمَا لَمۡ يُحَيِّكَ بِهِ ٱللَّهُ\nیہ لوگ جب اللہ کے رسول صلی اللہ علیہ وسلم کے پاس آتے تھے تو پست آواز میں کہتے تھے: “اَلسَّلَامُ عَلَيْکُمْ”؛ کیونکہ یہ اسلامی شعار ہے، اور اس میں سلامتى کے تمام معانی پائے جاتے ہے؛وہ اس کی جگہ: “أَنْعِمْ صَبَاحًا” (صبح بخیر) کہتے تھے، اور یہ زمانہ جاہلیت میں اہل عرب کے سلام کا طریقہ تھا، وہ اس جاہلی عادت کو چھوڑنا نہیں چاہتے تھے۔(ابن عاشور: ۲۸؍۳۱)\nاس وقت ہمارے نوجوانوں میں سلام کرنے کے کئی ایک طریقے رائج ہیں، ان کے بارے میں آپ کی کیا رائے ہے؟ اور سب سے افضل سلام کون سا ہے؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قِيلَ لَكُمۡ تَفَسَّحُواْ فِي ٱلۡمَجَٰلِسِ فَٱفۡسَحُواْ يَفۡسَحِ ٱللَّهُ لَكُمۡۖ\nاس آیت میں جس کشادگی کا حکم دیا گیا ہے، اس سے مراد دوسروں کے لئے مجالس میں جگہ بنانا ہے، اپنی جگہ چھوڑکر کھڑا ہو جانا مراد نہیں ہے ؛ كیونکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “لا يقم أحد من مجلسه، ثم يجلس الرجل فيه، ولكن تفسحوا، وتوسعوا”، یعنی: تم میں سے کوئی شخص اپنی مجلس سے نہ اٹھے کہ وہاں کوئی دوسراشخص بیٹھے، لیکن کشادگی اختیار کرواور وسعت دو ’’۔(ابن جزی: ۲؍۴۲۲)\nجس شرعی ادب کا اس آیت میں حکم دیا گیا ہے اس کی وضاحت کیجئے.\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قِيلَ لَكُمۡ تَفَسَّحُواْ فِي ٱلۡمَجَٰلِسِ فَٱفۡسَحُواْ يَفۡسَحِ ٱللَّهُ لَكُمۡۖ\n(يفسح الله لكم) یعنی: اللہ تعالىٰ تمہاری قبروں میں کشادگی دےگا، یا اللہ تعالىٰ تمہارے دلوں میں وسعت پیدا کردےگا، یا اس سے مراد: دنیا وآخرت میں اللہ تعالىٰ تمہارے لئے کشادگی پیدا کرے گا۔ (القرطبی: ۲۰؍۳۱۸)\nاللہ تعالىٰ کا اپنے بندوں کے لئے کشادگی کرنے کا کیا معنی ہے؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قِيلَ لَكُمۡ تَفَسَّحُواْ فِي ٱلۡمَجَٰلِسِ فَٱفۡسَحُواْ يَفۡسَحِ ٱللَّهُ لَكُمۡۖ\nعمل کا بدلہ اسی کی جنس سے دیاجاتا ہے، یعنی: جو دوسروں کے لئے کشادگی اختیار کرےگا اللہ تعالىٰ اس کے لئے کشادگی اختیار كرےگا، اور جو اپنے بھائی کو جگہ دےگا اللہ تعالىٰ اسے جگہ دےگا۔ (السعدی: ۸۴۶)\nاس آیت کی روشنی میں عمل کی جنس سے بدلہ دینے کے قاعدے (الجزاء من جنس العمل) کی وضاحت کیجئے.\nيَرۡفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ دَرَجَٰتٖۚ\nیعنی تم یہ نہ سمجھو کہ، اگر تم میں سے کوئی اپنے بھائی کے لئے اس کے کہنے پر کشادگی اپناتا ہے یا اس کے حکم پر نکل جاتا ہے، تو اس میں اس کے لئے ذلت و رسوائی ہے، بلکہ اس میں اللہ تعالیٰ کے نزدیک بلندی اور رفعت شان ہے۔ (ابن کثیر: ۴؍۳۲۶)\nکیا تمہارا اپنے بھائی کو کسی مجلس میں جگہ دینا تمہاری حق تلفی ہے؟\nيَرۡفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ دَرَجَٰتٖۚ\nآیت میں وارد (العلم) کا لام استغراقیہ نہیں ہے، بلکہ عہدیہ ہے، یعنی: وہ علم جس کے ساتھ اللہ تعالىٰ نے اپنے نبی کو مبعوث فرمایا، اور جب صحابہ کرام کو یہ علم عطا کیا گیا تو ان کی اتباع کرنا واجب ٹھہرا۔ (ابن قیم: ۳؍۱۴۳)\nیہ آیت علماء کرام کی اتباع کی اہمیت پر دلالت کرتی ہے، اسکی وضاحت کرو.\nwords\nبِمَا لَم يُحَيِّكَ بِهِ اللهُجيسا سلام الله تعاليٰ نے آپ كو نهيں كيا(وه كهتے تھے: السام عليك)تم پر موت.\nلَولاَكيوں نه.\nحَسبُهُمميں انهيں كفايت كر جاؤں گا.\nالمَصِيرُجائے رجوع ؛ ٹھكانا.\nإِنَّمَا النَّجوَىگناه اور سركشي كي سرگوشي.\nتَفَسَّحُواكه تم مجلس ميں وسعت پيدا كرو.\nانشُزُوااپني مجلسوں سے اٹھ جاؤ."],[544,"§المجادلۃ\ndeeds\nاپنے استاد، یا شیخ کے لئے دعاء کرو؛ کہ وہ تمہاری تعلیم پر صبر کررہا ہے.\nکھانے سے قبل، کھانے کے بعد، سونے سے قبل، سونے کے بعد پابندی کے ساتھ اللہ کے ذکر کا اہتمام کرو.\nباجماعت پنج وقتہ نماز کی پابندی کرو، خصوصا نماز عصر، اور نماز فجر کی.\nguid\nپابندی کے ساتھ سنت رسول کی اتباع کرنا.\nمنافقین، شیطان کے گروہ سے ہیں؛ لہذا ان سے ہوشیار رہو، اور ان کے اوصاف سے بھی بچے رہو.\nشیطانی گروہ کے اوصاف میں سے ہے: جھوٹ بولنا، خلاف باطن ظاہر کرنا، اور صحابہ کرام سے بغض وعداوت رکھنا.\nrefl\nفَإِذۡ لَمۡ تَفۡعَلُواْ وَتَابَ ٱللَّهُ عَلَيۡكُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَ\nیہاں(فَصَلُّوْا)کے بجائے (فَأَقِيمُوا الصَّلاةَ)؛ كا استعمال ہوا ہے، یعنی نماز ادا کرنے کے بجائے نماز قائم کرنے کا حکم ہے، یہ سمجھانے کے لئے کہ اس سے مراد: نماز کی مکمل پابندی کرنا، اس کے تمام حقوق کی ادائیگی ، اور اس کے کمالیات کی مکمل رعایت کےساتھ نماز پڑھنا ہے، صرف نماز ادا کر لینا مراد نہیں ہے۔(الألوسی: ۱۴؍۲۲۵)\nاس آیت کے اندر (فَصَلُّوْا)کے بجائے (فَأَقِيمُوا الصَّلاةَ)کیوں کہا گیا ہے؟\nفَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ\nیہ دونوں عبادتیں(نماز، زکاۃ) تمام بدنی و مالی عبادات کی اصل ہیں، پس جس نے بھی ان دونوں کو شرعی اصول وضوابط کی روشنی میں ادا کیا تو اس نے حقوق اللہ اور حقوق العباد کو ادا کردیا۔ (السعدی: ۸۴۷)\nخاص طور پر ان دونوں عبادتوں کو اللہ تعالىٰ نے کیوں ذکر کیا ہے؟\nوَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ ١٣\nالله اور اس كے رسول کی اطاعت میں اصل اعتبار اخلاص واحسان کا ہوتاہے؛ اسی لئے اللہ تعالىٰ نے فرمایا: (والله خبير بما تعملون) كیونكہ اللہ تعالىٰ کو ان کے اعمال کے متعلق بخوبی علم ہے، اور اللہ تعالیٰ کو ان کے متعلق جو کچھ علم ہے، اسی کی مطابق ان کو جزاملنے والی ہے۔(السعدی: ۸۴۷)\n(وأطيعوا الله ورسوله)کے فورا بعد (والله خبير بما تعملون) کیوں فرمایا؟\n۞أَلَمۡ تَرَ إِلَى ٱلَّذِينَ تَوَلَّوۡاْ قَوۡمًا غَضِبَ ٱللَّهُ عَلَيۡهِم مَّا هُم مِّنكُمۡ وَلَا مِنۡهُمۡ\nقشیری نے کہا: جس نے اس شخص کی موافقت کی جس پر غصہ کیاگیا ہے تو گویا اس نے اپنے آپ کو اس کے بھی غضب کا مستحق ٹھہرا لیا، جو اس پر غضبناک ہواتھا، چنانچہ جس نے اس شخص سے دوستی رچائی جس پر اللہ تعالىٰ غضبناک ہوا، تو اس پر بھی اللہ تعالیٰ کا غضب واجب ہو گیا۔ اور یہی اس کے ذلیل ورسوا اور محروم ہونے کے لئے کافی ہے۔(البقاعی: ۱۹؍۳۸۷)\nجس پر اللہ تعالیٰ غضبناک ہوا اس سے دوستی رچانے کی خطرناکی کیا ہے؟\nيَوۡمَ يَبۡعَثُهُمُ ٱللَّهُ جَمِيعٗا فَيَحۡلِفُونَ لَهُۥ كَمَا يَحۡلِفُونَ لَكُمۡ وَيَحۡسَبُونَ أَنَّهُمۡ عَلَىٰ شَيۡءٍۚ أَلَآ إِنَّهُمۡ هُمُ ٱلۡكَٰذِبُونَ ١٨\nجو جس پر جیئے گا اسےاسی پر موت آئیگی، جس طرح منافقین اس دنیا میں مومنوں کو دھوکہ دیتے ہیں، اور ان سے قسمیں کھاتے ہیں کہ وہ بھی مومن ہیں، تو جب قیامت قائم ہوگی، اور اللہ تعالیٰ اپنے تمام بندوں کو اکھٹا کرے گا، تو یہ اللہ تعالیٰ کے سامنے قسمیں کھائیں گے، جس طرح یہ مومنوں کے سامنے قسم کھا یا کرتے تھے، اور ان کا خیال ہوگا کہ یہ کسی چیز پر ہیں؛ کیونکہ ان کا کفر، نفاق، اور باطل عقائد ان کے دماغ میں راسخ ومضبوط ہوتے چلے گئے، یہاں تک کہ وه دھوکہ کھا گئے، اور انہیں گما ن ہو گیا کہ وہ کسی ایسی چیز پر ہیں، جس کا اعتبار کیاجائے گا، اور اس پر انھیں ثواب ملے گا۔ (السعدی: ۴۸۴)\nمنافقین کی دنیاوی اور اخروی حالت میں مشابہت پائی جاتی ہے، وہ کیسے؟\nإِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥٓ أُوْلَٰٓئِكَ فِي ٱلۡأَذَلِّينَ ٢٠\nجب یہ لوگ اپنے اتباع ومعاونین کی کثرت کی وجہ سے، اللہ اور اس کے رسول کی مخالفت كرتے ہیں، تو انہیں دیکھنے والے کو وہم ہو سکتا ہے کہ، یہی لوگ زیادہ معزز ہیں،ان سے زیادہ معزز کوئی نہیں ہے، تو اللہ تعالیٰ نے اس ظاہری دھوکہ کی نفی کرتے ہوئے فرمایا: (أولئك في الأذلين) یعنی:یہی لوگ ذلیل خوار و پستی میں ہیں۔حسن نے کہا: معصیت کےسبب ان کےدلوں میں ذلت وخواری ہے،اگرچہ ان کی سواریوں سے وادی گونجتی ہے۔ (البقاعی: ۱۹؍۳۹۵)\nدلوں پر معصیت ونافرمانی کا کیا اثر ہوتا ہے؟ اس آیت کی روشنی میں واضح کریں.\nكَتَبَ ٱللَّهُ لَأَغۡلِبَنَّ أَنَا۠ وَرُسُلِيٓۚ إِنَّ ٱللَّهَ قَوِيٌّ عَزِيزٞ ٢١\nزجاج نے کہا: رسولوں کے غلبہ کے دو طریقے ہیں: ان میں سے بعض کو اللہ تعالیٰ نے لڑائی کے لئے مبعوث فرمایا، تو وہ لڑائی کے ذریعے غالب ہوئے۔ اور بعض کو لڑائی کا حکم نہیں دیا گیا، تو وہ اپنے دلائل کے ذریعے غالب ہوئے۔ (بغوی:۴؍۳۴۹)\nپیغمبر اپنے جھٹلانے والوں پر کیسے غالب آتے ہیں؟ جبکہ بعض پیغمبروں کو ان کی قوم نے قتل کردیا؟\nwords\nالَّذِينَ تَوَلَّوا قَومًامنافقين جنهوں نے يهود سے دوستي اور موالات كي.\nجُنَّةًڈھال /جنگ ميں بچاؤ كا لباس.\nوَيَحسَبُونَوه اعتقاد ركھتے هيں.\nاستَحوَذَوه غالب آگيا۔ مسلط هو گئے.\nيُحَآدُّونَوه نافرماني كرتے هيں ؛ مخالفت كرتے هيں.\nالأَذَلِّينَمغلوب ؛ ذليل ؛ رسواء.\nلَأَغلِبَنَّميں ضرور مدد كروں گا."],[545,"§المجادلۃ ، الحشر\ndeeds\nکہو! اے اللہ میں تیری رضا اور جنت کا سوال کرتا ہوں.\nاللہ تعالیٰ سے تم اپنے لئے، اپنے والدین کے لئے، اپنے بھائیوں کے لئے، اور اپنے خاندان کے لئے ہدایت کی دعاء کرو.\nیہ دعا پڑھئے: (اَللّٰهُمَّ اِنِّيْ اَعُوْذُبِكَ مِنْ جَهْدِ الْبَلاَءِ، وَدَرَكِ الشَّقَاءِ، وَسُوءِ الْقَضَاءِ، وَشَمَاتَةِ الأَعْدَاءِ) اے اللہ میں تیری پناہ چاہتا ہوں بلاء کی مشقت سے، بدبختی کے پہنچنے سے،بری تقدیر سے،اور دشمنوں کے خوش ہونے سے.\nguid\nتم کوشش کرو کہ تمہاری بھائی چارگی، تمہاری محبت صرف اللہ کے لئے ہو، دنیاوی مصلحت کے لئے نہ ہو.\nاللہ اور اس کے رسول کی مخالفت کرنے والوں سے دشمنی مول لینا، خواہ وہ کافی قریبی رشتہ دار ہی کیوں نہ ہوں.\nکوئی بھی شخص، خواہ وہ کتنی ہی قوت کا مالک ہو جائے، اللہ تعالیٰ کے امر پر غالب نہیں آسکتا ہے.\nrefl\nلَّا تَجِدُ قَوۡمٗا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ يُوَآدُّونَ مَنۡ حَآدَّ ٱللَّهَ وَرَسُولَهُ\nاللہ تعالیٰ اور قیامت کے دن پر ایمان رکھنے والوں کو آپ اللہ اور اس کے رسول کی مخالفت کرنے والوں سے محبت رکھتے ہوئے ہرگز نہ پائیں گے، یعنی یہ دونوں چیزیں اکٹھا نہیں ہوسکتیں۔ چنانچہ کوئی بندہ اللہ تعالیٰ اور یوم آخرت پر حقیقی معنی میں ایمان لانے والا ہو ہی نہیں سکتا ہے جب تک وہ ایمان کے تقاضوں اور اس کے لوازم پر عمل کرنے والا نہ ہوجائے، جیسے: مومنوں سے محبت ودوستی رکھنا، اور جو ایمان نہ لائے اس سے بغض و دشمنی رکھنا۔(السعدی: ۸۴۸)\nاللہ اور یوم آخرت پر ایمان لانے، اور اللہ اور اس کے رسول کی مخالفت کرنے والوں سے بغض رکھنے کے ما بین کیا تعلق ہے؟\nلَّا تَجِدُ قَوۡمٗا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ يُوَآدُّونَ مَنۡ حَآدَّ ٱللَّهَ وَرَسُولَهُ\nبتلاؤکہ تمہیں کوئی ایسا مومن نہیں ملے گا جو اللہ اور اس کے رسول کی مخالفت کرنے والوں سے محبت رکھے؛کیونکہ نفس ایمان اس سے محبت رکھنے کی نفی کرتا ہے، جیسے دو ضدین میں سے ایک ضد دوسرے ضد کی نفی کرتی ہے، چناچہ جب ایمان پایا گیا تو اس کے ضد کی نفی ہو گئی، اور وہ ہےاللہ کے دشمنوں سے محبت کرنا، اسی طرح اگر کوئی آدمی اللہ کے دشمنوں سے دل سے محبت کرے تو یہ دلیل ہے اس بات کی کہ اس کے دل میں حقیقی ایمان نہیں ہے۔(ابن تیمیہ: ۶؍۲۵۷)\nاللہ تعالیٰ نے انہیں ایمان کے ساتھ متصف کیوں کیا جبکہ اللہ اور اس کے رسول کی مخالفت کرنے والوں سے محبت رکھنے کی نفی کی ہے؟\nرَضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُ\nاس آیت کے اندر ایک انوکھا راز پوشیدہ ہے، وہ یہ ہے کہ جب انھوں نے اللہ کے لئے خویش واقارب سے ناراضگی مول لی، تو اللہ تعالیٰ نے اس کا بدلہ اس طرح دیا کہ وہ ان سے راضی ہوگیا، اور انہیں ان دائمی نعمتوں اورعظیم فضل سے خوش کردیا جو انہیں عطا کیا۔ (ابن کثیر۔۴؍۳۲)\nاس آیت کی روشنی میں ،اللہ تعالیٰ کا مومنین سے راضی ہونے ، اور ان کا اللہ سے راضی ہونے کے سبب کی وضاحت کرو.\nأُوْلَٰٓئِكَ حِزۡبُ ٱللَّهِۚ أَلَآ إِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡمُفۡلِحُونَ ٢٢\n(أولئك) یعنی وہ لوگ خالص اللہ تعالیٰ سےمحبت کرنے کی وجہ سےاعلیٰ مقام پر فائز ہیں، کیونکہ وہ جانتے ہیں کہ نفع ونقصان کا مالک صرف اللہ تعالیٰ ہے۔(البقاعی: ۱۹؍۴۰۰)\nاللہ تعالیٰ کی حقیقی جماعت (پارٹی) کی علامت کیا ہے؟\nهُوَ ٱلَّذِيٓ أَخۡرَجَ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ مِن دِيَٰرِهِمۡ لِأَوَّلِ ٱلۡحَشۡرِۚ\nغیر اللہ پر بھروسہ مت کرو، جیسا کہ انہوں نے منافقین پر بھروسہ کیا، کیونکہ جس نے بھی کسی مخلوق پر بھروسہ کیا اس نے اسے ذلت ورسوائی تک پہنچا دیا۔ (البقاعی: ۱۹؍۴۱۱)\nاس شخص کی سزا کیا ہے جو اللہ تعالیٰ کو چھوڑکر کسی مخلوق پر بھروسہ کرے؟\nوَظَنُّوٓاْ أَنَّهُم مَّانِعَتُهُمۡ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنۡ حَيۡثُ لَمۡ يَحۡتَسِبُواْۖ\nیہ (یہود) اپنے قلعوں پر اترانے اور تکبر کرنے لگے، وہ سمجھ رہے تھے کہ یہ (مسلمان) انہیں کوئی نقصان نہیں پہنچا سکتے ہیں، اور نہ کوئی ان پر قدرت حاصل کر سکتا ہے، انکے نفوس اس سے مطمئن ہوگئے،جبکہ حقیقت یہ ہے کہ جس نے غیر اللہ پر بھروسہ کیا، وہ ذلیل ہوا، اور جس نے غیر اللہ کی پناہ لی وہ اس کے لئے وبال جان بن گیا۔ (السعدی: ۸۴۹)\nاس آیت میں توکل علی اللہ پر ابھارا گیا ہے، اور اسباب پر بھروسہ سے روکا گیا ہے۔ اس کی وضاحت کیجئے.\nيُخۡرِبُونَ بُيُوتَهُم بِأَيۡدِيهِمۡ وَأَيۡدِي ٱلۡمُؤۡمِنِينَ فَٱعۡتَبِرُواْ يَٰٓأُوْلِي ٱلۡأَبۡصَٰرِ ٢\nیعنی: جس نے امر الٰہی اور اس کے رسول کی مخالفت کی، اور اس کی كتاب کو جھٹلایا، اس کے انجام پر غور کرو،دنیا میں رسوا کر دینے والا اللہ کا عذاب اسے کیسے پکڑلیتا ہے، اور اس کے علاوہ اللہ نے اس کے لئےآخرت میں دردناک عذاب تیار کررکھا ہے۔ (ابن کثیر: ۴؍۳۳۱)\nبنو نضیر کے واقعے میں کون سی عبرت ہے؟\nwords\nيُوَآدُّونَوه محبت ركھتے هيں.\nحَآدَّدشمني ركھي.\nعَشِيرَتَهُمان كے اقرباء.\nوَأَيَّدَهُمانهيں قوت دي.\nبِرُوحٍ مِنهُاپني نصرت اور تائيد سے.\nلَم يَحتَسِبُواان كے ذهن ميں خيال بھي نه آيا تھا.\nوَقَذَفَاور ڈال ديا."],[546,"§الحشر\ndeeds\nکسی نومسلم، یا کسی ایسے طالب علم کو جو اپنے وطن سے دور ہو کوئی ہدیہ پیش کیجئے.\nجو کچھ اللہ تعالیٰ کے پاس ہے اسے ترجیح دیتے ہوئے تم اپنی آج کی افطاری کسی فقیر کو دے دو.\nیہ دعا پڑھئے: (اَللّٰهُمَّ قِنِيْ شُحَّ نَفْسِيْ) : اے اللہ مجھے تو میرے نفس کی بخیلی سے بچالے.\nguid\nسنت نبویہ نے جس کا حکم دیا ہے اسے لینا، اور جس سے روکا ہے اس سے دور رہنا ہے.\nبسا اوقات سچ قربانی چاہتا ہے.\nجو شخص اپنے نفس کے بخل سے بچ گیا وہ کامیاب ہو گیا.\nrefl\nذَٰلِكَ بِأَنَّهُمۡ شَآقُّواْ ٱللَّهَ وَرَسُولَهُۥۖ وَمَن يُشَآقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ ٤\nاللہ تعالیٰ کا قول: (ومن يشاقِّ الله فإن الله شديد العقاب) کے اندر اللہ کی مخالفت پر اکتفاکیا گیا ہے، کیونکہ اللہ کی مخالفت اس کے رسول کی مخالفت ہے۔ (الشوکانی: ۵؍۱۹۶)\nآیت کے آخری حصہ میں اللہ کی مخالفت کے ذکر پر اکتفاکیا گیا، اس کے رسول کی مخالفت کا ذکر نہیں کیا گیا، ایسا کیوں؟ جبکہ اس سے قبل دونوں کا ذکر کیا گیا؟\nكَيۡ لَا يَكُونَ دُولَةَۢ بَيۡنَ ٱلۡأَغۡنِيَآءِ مِنكُمۡۚ\n(مال فیء کا یہ حکم اس لئے ہے) تاکہ ما ل فیء سرداروں اور طاقتوروں کے مابین گردش کرتا نہ رہ جائے،(اگر وہ انہیں کے درمیان گردش کرتا رہا) تو وہ لوگ فقیروں اور کمزورں پر غالب آ جائیں گے۔ اور وہ اس طرح کہ اہل جاہلیت کو جب مال غنیمت حاصل ہو تا، تو ان کا سردار مال غنیمت میں سے ایک چوتھائی اپنے لئے خاص کرلیتا تھا، اللہ تعالیٰ نے اس حصہ کو اپنے نبی کے لئے خاص کردیا کہ اسے ان کے ما بین تقسیم کر دیں جن کے متعلق حکم ہوا ہے۔(البغوی: ۴؍۳۵۷)\nاللہ تعالیٰ کے اس قول: (كي لا يكون دولة بين الأغنياء منكم)سے کیا مراد ہے؟\nوَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمۡ عَنۡهُ فَٱنتَهُواْۚ\nآیت کے اخیر میں اس ٹکڑے سے بنو نضیر سے ملنے والے مال فیء سے بعض مجاہدین کومحروم رکھنے پر ان کے دل میں ابھرنےوالی تکلیف کا ازالہ مقصود ہے۔ (ابن عاشور: ۲۸؍۸۶)\nاحکام فیء کو اس بہترین خاتمے پر ختم کرنے کا مقصد کیا ہے؟\nوَلَا يَجِدُونَ فِي صُدُورِهِمۡ حَاجَةٗ مِّمَّآ أُوتُواْ وَيُؤۡثِرُونَ عَلَىٰٓ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةٞۚ\nان كے متعلق اللہ تعالیٰ نے دو چیزوں کی خبر دی کہ جو مال ان کے پاس ہے، ضرورت کے باوجود اسے وہ خرچ کرتے ہیں، اور ان کے بھائیوں پر اللہ کی طرف سے جو انعام ہوا ہے اسے نا پسند نہیں کرتے ہیں۔ اول الذکر بات کے برعکس بخل ہے، اور دوسری کی ضد حسد ہے، اس لئے بخل وحسد دونوں کی ایک ہی نوعیت ہے، کیونکہ حاسد کو پسند نہیں ہے کہ اس کے علاوہ دوسروں کو عطا کیا جائے، اور بخیل بھی دوسروں کو دینا ناپسند کرتا ہے۔(ابن تیمیہ: ۶؍۲۷۲)\nآیت کے اندر مومنوں کی دو عظیم صفت ذکر کی گئی ہیں، وہ کیا ہیں؟\nوَيُؤۡثِرُونَ عَلَىٰٓ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةٞ\nیہ ایثار صرف دنیا کے زائد معاملات میں ہے، عبادت وبندگی کے لئے مصروف اوقات میں ایثار درست نہیں، کیونکہ پوری کامیابی وکامرانی عبادت کے لئے مصروف اوقات میں بخیلی کرنے سے مل سکتی ہے، کیونکہ جو شخص اپنے اوقات میں بخیلی سے کام نہیں لیتا لوگ اسے روئے زمین پر بے یار ومددگار چھوڑدیتے ہیں، اس لئے وقت میں بخیلی اور اسے بچانے سے دل آباد ہو تا ہے، سرمایہ کی حفاظت ہو تی ہے، اور اس بات کی دلیل یہ ہے کہ اللہ تعالیٰ نے بھلائی کے کاموں میں سبقت کر نے کا حکم دیا ہے، اور یہ ایثار کے خلاف ہے۔ (ابن القیم: ۳؍۱۴۶)\nایثار کب محمود ہوتا ہے؟اور بخیلی کب محمود ہے،؟\nوَيُؤۡثِرُونَ عَلَىٰٓ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةٞ\nیہ مقام ان لوگوں کی حالت سے بڑھ کرہے جن کا ذکر اللہ تعالیٰ نے ان آیتوں میں کیا ہے: ﴿وَيُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ﴾ [الإنسان: ۸]، ﴿وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ﴾ [البقرة: ١٧٧)کیونکہ ان لوگوں نے صدقہ کیاحالانکہ وہ صدقہ کی ہوئی چیز سے محبت کرتے ہیں، اور ممکن ہے کہ انہیں اس کی حاجت و ضرورت نہ ہو، لیکن ایثار والے لوگ ایسے ہیں کہ انہیں اس کی اشد ضرورت ہے پھر بھی وہ خرچ کردیتے ہیں۔(ابن کثیر: ۴؍۳۳۸)\nکون زیادہ افضل ہیں؟ اپنے نفس پرترجیح دینے والے؟ یا مال کی محبت کے باوجود اسے خرچ کرنے والے؟\nوَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ٩\n(ایسے لوگ کامیاب ہیں) کیونکہ بندہ جب اپنے نفس کے بخل سے بچالیا جاتا ہے تو اس كا نفس اللہ اور اس کے رسول کے اوامرکو بجا لانے کے لئے نرم پڑجاتا ہے،اور وہ مطیع و فرمانبردار ہوکرکھلے دل سےحکم بجا لاتا ہے، اسی طرح وہ اللہ تعالیٰ کی منع کردہ چیزوں کو چھوڑنے پر راضی ہوجاتا ہے، اگر چہ وہ چیز بندے کے نزدیک محبوب ہو، اور اللہ تعالیٰ کی رضا حاصل کرنے کے لئے اللہ کے راستے میں مال خرچ کرنے لگتا ہے،اوراس طرح سے اسے فلاح وکامرانی حاصل ہوتی ہے۔ (السعدی: ۸۵۱)\nنفس کے بخل سے بچنا فلاح وکامیابی کا ذریعہ کیسے ہو سکتا ہے؟\nwords\nلِينَةٍكھجور ؛ كھجور كي ايك قسم.\nوَمَا أَفَاءَ اللهجو الله تعاليٰ نے مال فئے ديا(بني نضير كے اموال) فئے وه مال هوتا هے جو بغير جنگ كے حاصل هو جائے.\nفَمَا أَوجَفتُمتم نے گھوڑے نه دوڑائے تھے.\nرِكَابٍسواري كا اونٹ.\nدُولَةًملك ؛ هاتھوں هاتھ لينا.\nتَبَوَّءُوا الدَّارَاپنا ٹھكانا بنا ليا؛ مدينه كو وطن بنا ليا."],[547,"§الحشر\ndeeds\nیہ دعا مانگئے.\nشیطان مردود اور اس کے وسوسے سے اللہ کی پناہ طلب کیجئے.\nان آیات سے منافقین کی تین صفات مستنبط کیجئے.\nguid\nدل کو اہل ایمان کے تئیں بغض وکینہ سے پاک وصاف رکھنے کی حرص رکھئے.\nخوف وبزدلی یہودیوں کی لازمی صفت ہے.\nخالق سے زیادہ مخلوق سے ڈرنا کج فہمی کی علامت ہے.\nrefl\nوَٱلَّذِينَ جَآءُو مِنۢ بَعۡدِهِمۡ يَقُولُونَ رَبَّنَا ٱغۡفِرۡ لَنَا وَلِإِخۡوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلۡإِيمَٰنِ وَلَا تَجۡعَلۡ فِي قُلُوبِنَا غِلّٗا لِّلَّذِينَ ءَامَنُواْ رَبَّنَآ إِنَّكَ رَءُوفٞ رَّحِيمٌ ١٠\nجو صحابہ کے بعد آئے اس کی ایک تفسیر ہے کہ وہ تابعین ہیں، اور وہ لوگ جو قیامت تک صحابہ کی اتباع کرنے والے ہیں۔ مالک -رحمہ اللہ- نے اس آیت کو اسی پر محمول کیا ہے، اور کہا: یقیناً جس نے بھی کسی صحابی پر کیچڑ اچھالا مال غنیمت اور مال فیء میں اس کا کوئی حصہ نہیں ہے، کیونکہ اللہ تعالیٰ نے صحابہ کرام کے بعد آنے والوں کے متعلق فرمایا کہ وہ دعاء کرتے ہیں: (يقولون ربنا اغفر لنا ولإخواننا الذين سبقونا بالإيمان)؛ لہٰذا جس نے بھی اس کے بر خلاف کہا، وہ ان لوگوں سے نکل گیا جن کا تذکرہ اللہ تعالیٰ نے اس آیت میں کیا ہے۔ (ابن جزی: ۲؍۴۳۰)\nامام مالک -رحمہ اللہ –نے اس آیت سے کیسے استدلال کیا کہ جس نے بھی کسی صحابی پر کیچڑ اچھالا تو مال فیء میں اس کا کوئی حصہ نہیں ہوگا؟\nوَٱلَّذِينَ جَآءُو مِنۢ بَعۡدِهِمۡ يَقُولُونَ رَبَّنَا ٱغۡفِرۡ لَنَا وَلِإِخۡوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلۡإِيمَٰنِ\nایمان کے فضائل میں سے ہے کہ ایک مومن دوسرے مومن سے فائدہ اٹھاتا ہے، اور ایک دوسرے کے لئے دعائیں کرتا ہے، کیونکہ سب اس ایمان میں مشترک ہیں جو ان کے ما بین اخوت وبھائی چارگی کا متقاضی ہےجس کی ایک شاخ یہ ہے کہ ایک مومن دوسرے مومن کے لئے دعاء کرے۔ (السعدی: ۸۵۲)\nایمان کی ایک ایسی فضیلت ذکر کیجئے جس پر یہ آیت دلالت کرتی ہے.\nلَأَنتُمۡ أَشَدُّ رَهۡبَةٗ فِي صُدُورِهِم مِّنَ ٱللَّهِۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَفۡقَهُونَ ١٣\nحقیقی سمجھداری وعقلمندی یہ ہے کہ خالق کا خوف اس سے امید اور اس کی محبت ، دوسری تمام چیزوں پر مقدم ہو، بقیہ تمام ان کے تابع ہوں۔(السعدی:۸۵۲)\nبندے کے سمجھدار ہونے کی علامت کیا ہے؟\nلَأَنتُمۡ أَشَدُّ رَهۡبَةٗ فِي صُدُورِهِم مِّنَ ٱللَّهِۚ\nتمہاری ہیبت ان کے سینوں میں ہے کہنے کی وجہ اس بات کی طرف اشارہ مقصودہے کہ یہ ہیبت بہت مخفی ہے،یعنی وہ ظاہر تو یہ کرتے ہیں کہ مسلمانوں سے جنگ کرنے کے لئے تیار ہیں، اور اپنی شجاعت وبہادری کے دعوے بھی کرتے ہیں، تاکہ مسلمانوں پر ان کی ہیبت طاری ہو جائے، لیکن وہ اس طرح ہیں نہیں، اللہ تعالیٰ نے اپنے پیغمبر کو ان کی اندرونی حالت سے با خبر کردیا ۔(ابن عاشور: ۲۸؍۱۰۳)\nکیوں کہا گیا کہ ہیبت ان کے سینوں میں ہے؟ اس وصف سے مسلمانوں کو کو ن سا فائدہ پہونچا؟\nبَأۡسُهُم بَيۡنَهُمۡ شَدِيدٞۚ تَحۡسَبُهُمۡ جَمِيعٗا وَقُلُوبُهُمۡ شَتَّىٰۚ\nقشیری نے کہا: دلوں میں نفرت واختلاف ركھتے ہوئے جسمانی طور پر یكجا ہونا تمام فساد کی جڑ ہےہرذلت ورسوائى كااصل سبب ہے، اور دشمنوں کے جری ہوجانے کی متقاضی ہے۔ اس كے بر عکس دلوں میں اتفاق کا پایا جانا، عزم وہمت میں برابر ہونا، اور مقاصد میں متفق ہونا ہر کامیابی ، اورتمام سعادت کا ذریعہ ہے۔ (البقاعی: ۱۹؍۴۵۲)\nدلوں میں نفرت واختلاف کے نقصانات کیا ہیں؟\nبَأۡسُهُم بَيۡنَهُمۡ شَدِيدٞۚ تَحۡسَبُهُمۡ جَمِيعٗا وَقُلُوبُهُمۡ شَتَّىٰۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡقِلُونَ ١٤\nان کے پاس کوئی ایسا دین ہے ہی نہیں جو انہیں ایک پلیٹ فارم پر جمع کرے، کیونکہ انہیں بخوبی معلوم ہے کہ وہ باطل پر ہیں، وہ ہواپرست ہیں، اور ہوا پرستی اختلاف کی جڑ ہے، جبکہ عقل نقطہ اجتماع ہے، جس طرح ہوا پرستی نقطہ اختلاف ہے۔ (البقاعی: ۱۹؍۴۵۳)\nیہود عقل کے کورے ہوتے ہیں، اسکی کیا دلیل ہے؟\nبَأۡسُهُم بَيۡنَهُمۡ شَدِيدٞۚ تَحۡسَبُهُمۡ جَمِيعٗا وَقُلُوبُهُمۡ شَتَّىٰۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡقِلُونَ ١٤\nاس آیت میں مومنوں کو تربیت دی گئی ہے کہ وہ آپسی اختلاف وقطع تعلق سے بچیں، اور انہیں معلوم رہے کہ کوئی بھی امت اپنے دشمنوں پر اس وقت تک سخت پکڑ والی نہیں ہو سکتی جب تک ان کےدل متفق نہ ہوں۔ (ابن عاشور: ۲۸؍۱۰۶)\nاس آیت میں دشمنوں سے مقابلہ کیلئے اتحاد واتفاق کی اہمیت کی طرف اشارہ کیا گیا ہےاسے واضح کیجئے.\nwords\nغِلًاحسد ؛ بغض.\nلإِخوَانِهِمُاپنے بھائيوں سے مراد يهودِ بني نضير هيں.\nجُدُرٍديواريں.\nبَأسُهُم بَينَهُمان كے مابين عداوت و دشمني.\nشَتَّىمتفرق.\nوَبَالَ أَمرِهِمان كے كفر كا برا انجام.\nكَمَثَلِ الشَّيطَانِيهود كے ساتھ وعده كرنے ميں منافقين كا مدد كرنے كا وعده ؛ جيسے شيطان كي مثال."],[548,"§الحشر\ndeeds\nگذشتہ ہفتہ جو کام آپ نے کئے ہیں ان پر غور کیجئے، اور تین ایسی عبادتیں ذکرکیجئے جنہیں آپ نے پچھلے ہفتہ کیا ہے۔ اور اس پر اللہ تعالیٰ کی تعریف کیجئے۔ پھر ایسی تین غلطیاں یاد کیجئے جو آپ سے صادر ہوئی ہیں، اور ان سے اللہ تعالیٰ کی بخشش ومغفرت طلب کیجئے.\nآج گھر میں داخل ہونے ، گھر سے نکلنے کی دعا، اسی طرح صبح وشام کے اذکار کی پوری پابندی کیجئے.\nاس سورہ میں مذکور اللہ تعالیٰ کے اچھے ناموں سے اسے پکاریئے.\nguid\nہمیشہ یوم آخرت کو یاد کیجئے، اور اسے اپنا نصب العین بنا لیجئے.\nتقویٰ پیدا کرنے والی چیزیں بہت ہیں، انہی میں سے ہےیوم آخرت کی یاد، اور اللہ تعالیٰ کی عظمت کا إحساس.\nتلاوت قرآن کریم کے دوران اپنے اندر خشوع وخضوع پیدا کرنے کی کوشش کریں.\nrefl\nوَلۡتَنظُرۡ نَفۡسٞ مَّا قَدَّمَتۡ لِغَدٖۖ\n(قدَّمت) ماضی کا صیغہ ہے، اس کا مقصد ہے عمل میں جلدی کرنے پر ابھارنا، اور تاخیر نہ کرنا، کیونکہ جسے اس نے زمانہ ماضی میں کیا ہے اسی کے وہ مالک ہیں، جہاں تک مستقبل کی بات ہے تو وہ اس کے اختیار میں نہیں ہے، اور نہ اس کے متعلق اسے کوئی علم ہے کہ اس میں کیا ہوگا۔ ﴿وَمَا تَدۡرِي نَفۡسٞ مَّاذَا تَكۡسِبُ غَدٗا﴾ [لقمان: ۳۴].[لقمان: ٣٤]۔(الشنقیطی: ۸؍۵۴)\n(قَدَّمَتْ) کو ماضی کے صیغے کے ساتھ لانے کی کیا وجہ ہے؟\nوَلۡتَنظُرۡ نَفۡسٞ مَّا قَدَّمَتۡ لِغَدٖۖ\nبندے کے اپنے نفس کا محاسبہ كرنے کے سلسلہ میں یہ آیت اصل ہے، مناسب ہوگا کہ بندہ اپنے نفس کا جائزہ لے، اگر اسے کوئی لغزش نظر آئے تو اس کا ازالہ کرے ، اور ہر اس چیز سے باز آجائے جو اس لغزش کا سبب بن سکتی ہے، اور اللہ تعالیٰ سے خالص توبہ کرے، لیکن اگر لغزش نہیں، بلکہ اللہ کے اوامر میں سے کسی امر میں کوتاہی نظر آئے تو اپنے رب سے، پختگی کے ساتھ اس کی تکمیل کی مدد مانگے، اور اس میں اپنی پوری کوشش صرف کردے، اور اپنے اوپر اللہ تعالیٰ کی نعمت ، اور اللہ تعالیٰ کے حقوق کی ادائیگی میں اپنی کوتاہی وتقصیر کے مابین موازنہ کرکے دیکھے، یقیناً اپنی تقصیر وکوتاہی پر ضرور شرمندہ ہوگا۔(السعدی: ۸۵۳)\nاس آیت کی روشنی میں محاسبہ نفس پر گفتگو کیجئے.\nوَلَا تَكُونُواْ كَٱلَّذِينَ نَسُواْ ٱللَّهَ فَأَنسَىٰهُمۡ أَنفُسَهُمۡۚ\nاللہ تعالیٰ بندہ کو اس کی اپنی ہی جان سے غافل کردیتا ہے اس کی اعلیٰ ترین لذتوں، اس کی سعادت مندی، اور فلاح وکامرانی کے اسباب اور اس کے کمال کے ذرائع وغیرہ جیسے تمام چیزوں سے اللہ اسے غافل کردیتا ہے، پھر یہ نہ کبھی اس کے دل میں کھٹکتی ہیں، اور نہ کبھی ان کے متعلق غور وفکر کرتا ہے، اور نہ کبھی ان چیزوں میں اس کی رغبت پیدا ہوتی ہے،اسی طرح اس کے اندر موجود عیوب ونقائص کو اس طرح بھلادیتا ہے، کہ اس کے ازالے سے متعلق کبھی سوچتا ہی نہیں۔ (ابن قیم: ۳؍۱۴۷)\nبندہ اپنے نفس کو کیسے بھلا دیتا ہے؟\nوَلَا تَكُونُواْ كَٱلَّذِينَ نَسُواْ ٱللَّهَ فَأَنسَىٰهُمۡ أَنفُسَهُمۡۚ أُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ ١٩\n(فأنساهم أنفسهم) گویا کہ سائل نے سوال کیا؟ اللہ تعالیٰ کا ان کو ان کے نفس سے غافل کرنے کا اثر کیا ہوا؟ تو اس کا جواب یہ ہے کہ اس کی وجہ سے یہ برے اعمال کرنے میں فسق وفجور کے اس آخری انتہا کو پہنچ گئے ہیں، جہاں پر ان کے لئے یہ کہنا مناسب ہوگیا ہے کہ: ان کے فسق سے بڑا فسق نہیں ہو سکتا ہے۔ (ابن عاشور: ۲۸؍۱۱۴)\nاللہ تعالیٰ کا ان کو انکے نفس سے غافل کرنے کا اثر کیا ہوا؟\nلَوۡ أَنزَلۡنَا هَٰذَا ٱلۡقُرۡءَانَ عَلَىٰ جَبَلٖ لَّرَأَيۡتَهُۥ خَٰشِعٗا مُّتَصَدِّعٗا مِّنۡ خَشۡيَةِ ٱللَّهِۚ\nاس آیت میں قرآن کے مواعظ پر تدبر وتأمل کرنےپر ابھارا گیا ہے، اور کہا گیا کہ ترک تدبر کا کوئی بھی عذر قابل قبول نہیں ہوگا، کیونکہ اگر پہاڑ کو عقل دے دی جاتی، اور اس قرآن کے ذریعے پہاڑ کو بھی مخاطب کیا جاتاتو اس کے مواعظ وعبر کے سامنے وہ سر تسلیم خم کر دیتا، اورتم دیکھتے کہ اس کے سخت وبوجھل ہونے کے با وجود اللہ تعالیٰ کے خوف سے وہ ریزہ ریزہ ہو جاتا۔ (القرطبی: ۲۰؍۳۸۸)\nاس بیان ووضاحت کے بعد کیا قرآن میں ترک تدبر کا عذر قابل قبول ہو سکتا ہے؟\nهُوَ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَۖ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِۖ هُوَ ٱلرَّحۡمَٰنُ ٱلرَّحِيمُ ٢٢\nاس آیت کے اخیر میں اللہ تعالیٰ نے توحید الوہیت پر دلیل پیش کی جس میں اللہ تعالیٰ کا کوئی شریک نہیں ہو سکتا ہے، فرمایا: (عالم الغيب والشهادة). یعنی: (اللہ تعالیٰ معبودِبرحق ہے اس لئے کہ) اللہ تعالیٰ غیب وحاضر کا جاننے والا ہے، اللہ تعالیٰ نے دوسری جگہوں میں بھی اسے اللہ کی وحدانیت کی دلیل کے طور پرپیش کیا ہے۔(الشنقیطی: ۸؍۶۸)\nتوحید الوہیت کی دلیل کیا ہے؟\nهُوَ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡمَلِكُ ٱلۡقُدُّوسُ ٱلسَّلَٰمُ ٱلۡمُؤۡمِنُ\nاللہ تعالیٰ کے مختلف اوصاف کے بعد وصف (الْمُؤْمِنُ) ذکر نے کا مقصد اس وہم وغلط فہمی سے بچانا ہے جو وصف (ملک) سے پیدا ہو سکتا ہے، کہ اللہ کی ذات دیگر بادشاہوں کی طرح ہے جو نقائص وعیوب سے پاک نہیں ہیں، تو سب سے پہلے وصف (القدوس) کے ذریعے اللہ تعالیٰ کی نقائص و عیوب سے پاکی بیان کی گئی ، پھر (المؤمن) کے ذریعے باطنی امور میں غدر وفریب سے اس کی پاکی بیان کی گئی ہے، اور وصف (السَّلٰمُ) کے ذریعے ظاہری امور میں ظلم وجور سے اس کی پاکی بیان کی گئی ہے۔ (ابن عاشور: ۲۸؍۱۲۱)\nوصف (الملك) کے بعد اللہ تعالیٰ کے اسمائے حسنىٰ: (القدوس السلام المؤمن) بذکر کرنے کا مقصد کیا ہے؟\nwords\nوَلتَنظُراور ضرور غور و فكر كرنا چاهيے.\nفَأَنسَاهُم أَنفُسَهُمان كا اپنا آپ ان كو بھلاديا۔ وه اپني آخرت سے هي غافل هو گئے.\nمُتَصَدِّعًاپھٹا هوا.\nوَالشَّهَادَةِهر اعلانيه چيز كا جاننے والا ؛ حاضر و موجود.\nالمُؤمِنُرسولوں كے معجزات كي تصديق كرنے والا."],[549,"§الممتحنہ\ndeeds\nپڑھئے: (رَبَّنَا هَبْ لَنَا مِنْ اَزْوَاجِنَا وَ ذُرِّيّٰتِنَا قُرَّةَ اَعْيُنٍ وَّ اجْعَلْنَا لِلْمُتَّقِيْنَ اِمَامًا).\nیہ دعا بھى پڑھتےرہئے\"ربنا عليك توكلنا، وإليك أنبنا، وإليك المصير\".\nیہ دعا بھى كرتےرہئے\"ربنا لا تجعلنا فتنةً للذين كفروا، واغفر لنا ربنا؛ إنك أنت العزيز الحكيم\".\nguid\nكافروں کی چال اور ان كے ان تمام طریقوں سے بچنا جن كے ذریعے وه چاہتےہیں كہ مسلمانوں كا تعلق اسلام سے كمزور ہوجائے.\nآپ كى اولاد اور رشتہ داریاں اس وقت آپ كو كچھ بھى فائده نہیں پہنچائیں گى اگر ان كى خاطر آپ نے الله کا حكم چھوڑ دیاہے.\nالله پر بھروسہ كرنا اور اپنے معاملات كو اس كے حوالے كردینا.\nrefl\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ عَدُوِّي وَعَدُوَّكُمۡ أَوۡلِيَآءَ تُلۡقُونَ إِلَيۡهِم بِٱلۡمَوَدَّةِ\n(دشمنوں کو دوست نہ بناؤ)کیونکہ محبت پنپنے سے مدد اور دوستی کا معاملہ ضرور پیش آتا ہے، پھر بنده ایمان سے نكل كر اہل كفر كى جماعت میں شامل ہوجاتاہے اور اہل ایمان كى جماعت سے نكل جاتاہے۔(السعدى: ۸۵۵)\nكافروں سے محبت كرنے سے منع كیوں كیا گیا ہے؟\nوَأَنَا۠ أَعۡلَمُ بِمَآ أَخۡفَيۡتُمۡ وَمَآ أَعۡلَنتُمۡ\nپھر تمہارے چھپانے كا كیا فائده ہے جب تم جانتےہو كہ میں اس سے واقف ہوں۔ اور اگر تمہارا یہ گمان ہے كہ میں اسے نہیں جانتا تو یہ اور بڑى مصیبت ہے۔(البقاعى: ۱۹؍۴۸۸)\nالله تعالىٰ نے یہ خبر دى ہے كہ وه خلوت اور جلوت سارى باتوں سے آگاه ہے، اس کا كیا فائده ہے؟\nإِن يَثۡقَفُوكُمۡ يَكُونُواْ لَكُمۡ أَعۡدَآءٗ وَيَبۡسُطُوٓاْ إِلَيۡكُمۡ أَيۡدِيَهُمۡ وَأَلۡسِنَتَهُم بِٱلسُّوٓءِ وَوَدُّواْ لَوۡ تَكۡفُرُونَ ٢\nدین مومنوں كےنزدیك ان كى روحوں سے بھى زیاده عزیز ہے ، کیونکہ وہ دین كےلئے اپنى جان قربان كردیتےہیں، اور زك پہنچانے كیلئے دشمن كےنزدیك سب سے اہم وه چیز ہوتى ہے جو اس کے مخالف كے یہاں سب سے اہم ہو۔ (الألوسی: ۱۴؍۲۶۳)\nمومنوں كے نزدیك عزیز ترین چیز كیا ہوتى ہے؟ نیز كفار كےنزدیك سب سے اہم کیا ہوتا ہے ؟\nلَن تَنفَعَكُمۡ أَرۡحَامُكُمۡ وَلَآ أَوۡلَٰدُكُمۡۚ يَوۡمَ ٱلۡقِيَٰمَةِ يَفۡصِلُ بَيۡنَكُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ ٣\nجب حاطب رضی اللہ عنہ نے یہ عذر پیش كیا كہ كفار مكہ کے درمیان ان کے بال بچے اور رشتے دار موجود ہیں، تو الله تعالىٰ نے بیان كیا كہ قیامت كے دن اولاد اور اہل وعیال كچھ بھى فائده نہیں دیں گےاگر الله كى نافرمانى ان كى وجہ سے كى گئى ہوگى۔ (قرطبى: ۲۰؍۴۰۲)\nكیا كوئى مسلمان اگر اپنى اولاد اور مال ومتاع كى خاطر مسلمانوں كے خلاف جاسوسى كرتا ہے تو اسے معاف كردیا جائےگا؟\nقَدۡ كَانَتۡ لَكُمۡ أُسۡوَةٌ حَسَنَةٞ فِيٓ إِبۡرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ إِذۡ قَالُواْ لِقَوۡمِهِمۡ إِنَّا بُرَءَٰٓؤُاْ مِنكُمۡ وَمِمَّا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ كَفَرۡنَا بِكُمۡ وَبَدَا بَيۡنَنَا وَبَيۡنَكُمُ ٱلۡعَدَٰوَةُ وَٱلۡبَغۡضَآءُ أَبَدًا حَتَّىٰ تُؤۡمِنُواْ بِٱللَّهِ وَحۡدَهُ\nالله كى خاطر محبت كرنا اور اسى كى خاطر دشمنى كرنا ایمان كا سب سے مضبوط كڑا ہے ، اس لئے ان دونوں سے غفلت برتنا بالكل مناسب نہیں ہے۔ (الألوسی: ۱۴؍۲۶۳)\nایمان كا سب سے مضبوط كڑا كیا ہے؟\nقَدۡ كَانَتۡ لَكُمۡ أُسۡوَةٌ حَسَنَةٞ فِيٓ إِبۡرَٰهِيمَ وَٱلَّذِينَ مَعَهُ\nیعنی مسلمانوں كو چاہئے كہ وه اپنے رسول صلی اللہ علیہ وسلم كى رضا كے تابع رہیں جس طرح پہلے كے مسلمان ابراہیم علیہ السلام کے تابع تھے۔ (ابن عاشور : ۲۸؍۱۴۳)\nابراہیم علیہ السلام اور ان كے ساتھ کے مومنوں كى اقتدا كرنے كا حكم كس بات پر دلالت كرتاہے؟\nرَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلَّذِينَ كَفَرُواْ\nیعنی ہمارےگناہوں كى وجہ سے انہیں ہم پر مسلط نہ كرنا كہ وه ہمیں فتنے میں مبتلا کریں اور خود كو بھى فتنے میں ڈالیں ، كیونكہ جب وه اپنا غلبہ دیکھیں گے تو سمجھنے لگیں گے كہ حق پر وہى ہیں اور ہم باطل پر ہیں ، پھر كفر اور سركشى میں وه مزید بڑھ جائیں گے۔(السعدى: ۸۵۶)\nایك مسلمان كافر كیلئے فتنہ كیسے بنتاہے؟\nwords\nأَولِيَاءَخاص همنشين ؛ محبوب لوگ.\nتُلقُونَتم پيغام بھيجتے هو.\nيَثقَفُوكُموه تم پر كامياب هو جائيں.\nوَيَبسُطُواوه اپنے هاتھ بڑھائيں.\nيَفصِلُ بَينَكُماطاعت گزار اور نافرمان ميں تفريق كرے گا.\nأُسوَةٌقدوه / پيشوا.\nأَنَبنَاهم نے رجوع كيا ؛ توبه كي.\nالمَصِيرُمرجع ؛ ٹھكانا."],[550,"§الممتحنہ\ndeeds\nدعا كریں كہ الله تعالىٰ گمراہوں اور كافروں كو ہدایت دے.\nتالیف قلب كے طور پر كسى كافر كو ہدیہ دیں.\nكسى ایسے مسلمان كو یاد كریں جس کے ساتھ آپ نے كبھى غلطى كى ہو پھر اس سے معافى مانگیں یا اس كے لئے الله سے دعا كریں.\nguid\nمسلمان كى زندگى میں اسوه اور نمونے كى اہمیت.\nغیر حربى كافر كےساتھ معاملات اور اسكے ساتھ اچھا برتاؤ كرنے كا جواز.\nعدل وانصاف ہر ایك كےساتھ ہو چاہے دوست ہو یا دشمن.\nrefl\nوَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ ٦\n(ومن يتول) (اور جو منہ موڑے گا) یعنى اسلام سے اور ان نصیحتوں كو قبول كرنےسے (فإن الله هو الغني)(تو الله بےنیاز ہے) یعنى اس نے انہیں عبادت و بندگی کا حکم اس لئے نہیں دیا ہے کہ وہ ان کا محتاج ہے۔ (الحميد) (بڑا حمدوالا ہے) یعنى اپنى ذات اور صفات میں۔ (القرطبى: ۲۰؍۴۰۵)\nالله تعالىٰ كےان دونوں ناموں پر آیت ختم كرنے كى كیا مناسبت ہے؟\n۞عَسَى ٱللَّهُ أَن يَجۡعَلَ بَيۡنَكُمۡ وَبَيۡنَ ٱلَّذِينَ عَادَيۡتُم مِّنۡهُم\nالله تعالىٰ نے جب مسلمانوں كو كافروں كےساتھ دشمنى كرنے اور ان سے قطع تعلق كا حكم دیا تو انہوں نے اس پر عمل كیا گرچہ ان كے اور كافروں كے درمیان قرابت دارى تھى، اورالله تعالىٰ كو ان كى سچائى كا پتہ چلا تو اس آیت كے ذریعہ انہیں مانوس كیا اور وعده كیا كہ ان كےدرمیان ایك دن محبت پیدا كردےگا ، اور یہ محبت فتح مكہ كےوقت پورى ہوئى جس وقت قریش كے سارے لوگ اسلام لےآئے۔(ابن جزى: ۲؍۴۳۶)\nكافروں سے براءت كى گفتگو كےبعد اس آیت كى كیا مناسبت ہے؟\n۞عَسَى ٱللَّهُ أَن يَجۡعَلَ بَيۡنَكُمۡ وَبَيۡنَ ٱلَّذِينَ عَادَيۡتُم مِّنۡهُم مَّوَدَّةٗۚ وَٱللَّهُ قَدِيرٞۚ\n(عسى الله أن يجعل بينكم وبين الذين عاديتم منهم مودة) (قریب ہے الله تعالىٰ تمہارے اور تمہارے دشمنوں كےدرمیان محبت پیدا كردے) اس كا سبب ان كا ایمان كى طرف رجوع كرنا ہے۔ (والله قدير) (الله قدرت والا ہے) ہر چیز پر، انہیں میں سے دلوں كو ہدایت دینا اور انہیں ایك حالت سے دوسرى حالت كى طرف پھیرنا بھى ہے۔(السعدى: ۸۵۶)\nمشركین كى دشمنى محبت میں بدلنے كے امكان كو ذكر كرنے كےبعد الله تعالىٰ نے اپنى قدرت كا ذكر كیوں كیا ہے؟\nلَّا يَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ لَمۡ يُقَٰتِلُوكُمۡ فِي ٱلدِّينِ وَلَمۡ يُخۡرِجُوكُم مِّن دِيَٰرِكُمۡ أَن تَبَرُّوهُمۡ وَتُقۡسِطُوٓاْ إِلَيۡهِمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ ٨\nجب الله تعالىٰ نے (مطلق طور پر) بیان كردیا كہ مومنوں کے لئے كافروں كےساتھ دوستى نہ کرنا اور دشمنى کرنا بہتر اورمناسب ہے تو اب تفصیلى بات بتا رہاہے كہ ان میں سے كس طرح كے لوگوں كےساتھ بھلائى كرنا جائز ہے اور كس كےساتھ جائز نہیں ہے چنانچہ فرمایا: (لا ينهاكم الله عن الذين لم يقاتلوكم في الدين...)(جو دین كى خاطر تم سے نہیں لڑتےہیں ان كے ساتھ بھلائى كرنے سے الله تمہیں نہیں روكتاہے)۔(الشوكانى : ۵؍۲۱۳)\nاس آیت كا ماقبل سے كیا تعلق ہے؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا جَآءَكُمُ ٱلۡمُؤۡمِنَٰتُ مُهَٰجِرَٰتٖ فَٱمۡتَحِنُوهُنَّۖ\nقشیرى نے كہا: خلاصہ یہ كہ امتحان معرفت كا راستہ ہے ، اور لوگوں كى اصلیت كا پتہ تجربےكے بعد ہى چلتاہے، اور بغیر تجربہ كئے اگر كوئى كام كرتا ہےتو اسے ندامت اٹھانى پڑتى ہے۔ (البقاعى : ۱۹؍۵۱۴)\nامتحان(لوگوں كو آزمانے ) كى كیا اہمیت ہے ؟\nفَإِنۡ عَلِمۡتُمُوهُنَّ مُؤۡمِنَٰتٖ فَلَا تَرۡجِعُوهُنَّ إِلَى ٱلۡكُفَّارِۖ\nاس میں اس بات كى طرف اشاره ہے كہ ایمان كا پتہ لگانا یقینى طور پر ممكن ہے۔(ابن كثیر: ۴؍۳۵۱)\nكیا كسى كے ایمان كاپتہ لگانایقینى طور پر ممكن ہے؟\nفَإِنۡ عَلِمۡتُمُوهُنَّ مُؤۡمِنَٰتٖ فَلَا تَرۡجِعُوهُنَّ إِلَى ٱلۡكُفَّارِۖ لَا هُنَّ حِلّٞ لَّهُمۡ وَلَا هُمۡ يَحِلُّونَ لَهُنَّۖ وَءَاتُوهُم مَّآ أَنفَقُواْۚ\nمسلمان عورت كو روكنے كى صورت میں الله تعالىٰ نے حكم دیا كہ اس كے سابق شوہر كو اسكا كیا ہوا خرچ لوٹا دیں، اور یہ ایفائے عہد میں سےہے ؛ كیونكہ جب اسلام كى حرمت كى وجہ سے اسے اس كے اہل سے روك دیا گیا تو پھر مال كو لوٹا نے كا حكم ہوا تاكہ بیوى اور مال دونوں طرح سے اسے خساره نہ ہو ۔ (القرطبى: ۲۰؍۴۱۴)\nآیت كى روشنى میں ایفائے عہد كى کوئی ایك صورت ذكر كریں.\nwords\nيَرجُو اللهَوه الله تعاليٰ سے خير كي توقع ركھتا هے.\nيَتَوَلَّانبياء كي اقتداء سے منه موڑتا هے.\nالحَمِيدُقابل تعريف؛ اپني ذات و صفات اورافعا ل ميں.\nوَتُقسِطُوااور تم ان كے ساتھ عدل كرو.\nوَظَاهَرُوااور مدد كي.\nأَن تَوَلَّوهُميه كه تم ان كي مدد كرو ؛ اور ان سے محبت ركھو.\nفَامتَحِنُوهُنّان كے ايمان كا امتحان لو ؛ تاكه ان كي سچائي كا پته چل جائے."],[551,"§الصف ، الممتحنہ\ndeeds\nسو مرتبہ اللہ تعالیٰ کی تسبیح بیان کرو.\nکسی عمل صالح کی تعیین کرو،اور عملی طور پر اسے انجام دو، پھر اپنے دوستوں کو ایک رسالہ بھیج کر انہیں اس پر عمل کرنے پر ابھارو، تاکہ تم اس چیز پر عمل کرنے والوں میں سے ہو جاو جسے تم کہتے ہو.\nکسی ایسے عالم یا داعی کو یاد کرو جس کو کسی کی بد تمیزی اور سوء ادب کا سامنا کرنا پڑا ہو،اور اپنے دوستوں سے اس کی خوبیاں بیان کرو.\nguid\nچاہئے کہ تمہاری زندگی منظم ومرتب ہو، کیونکہ جو اللہ کے راستے میں قتال کرتے ہیں صف بستہ ہوکر اللہ تعالیٰ انہیں پسند فرماتاہے، اسی طرح ان لوگوں کو بھی پسند فرماتا ہے جو صف بستہ ہوکر نماز ادا کرتے ہیں.\nانبیاء کرام نے تکلیفوں پر صبر کیا، اور وہ دعاۃ کے لئے نمونہ ہیں.\nاللہ تعالیٰ کی اطاعت وفرماں برداری میں انحراف سے بچنا چاہئے، کیونکہ یہ دل کے انحراف وگمراہی کا سبب ہے.\nrefl\nوَلَا يَعۡصِينَكَ فِي مَعۡرُوفٖ\nرسول اللہ صلی اللہ علیہ وسلم کی نافرمانی اچھے کاموں ہی میں ہو سکتی ہے، کیونکہ وہ کسی منکر کا حکم نہیں دے سکتے ہیں، اس کے باوجود آیت کے اندر کہا گیا: بھلائی میں وہ آپ کی نافرمانی نہ کریں۔ تو اس کے اندر دلالت ہے اس بات پر کہ ولی أمر کی اطاعت صرف اچھے کاموں میں ضروری ہے۔(ابن تیمیہ: ۶؍۲۹۵)\nنبی صرف بھلائی کا ہی حکم دیتے ہیں، تو پھر کیوں کہا گیا کہ کسی اچھے کام میں نبی کے حکم کی نافرمانی نہ کرو؟\nوَلَا يَعۡصِينَكَ فِي مَعۡرُوفٖ\n(بھلائی میں وہ آپ کی نافرمانی نہ کریں) یعنى وہ بھلائی جس کا آپ انہیں حکم دیتے ہیں، اور جس برائی سے روکتے ہیں، یہاں پر معروف کی قید لگانا اس کے با وجود کہ رسول اللہ صلی اللہ علیہ وسلم صرف بھلائی کا ہی حکم دیتے ہیں اس بات پر تنبیہ کے لئے ہے کہ اللہ کی نافرمانی میں کسی بھی مخلوق کی اطاعت جائزنہیں ہے۔ (الألوسی: ۱۴؍۲۷۴)\nاس آیت کے اندر معروف میں نا فرمانی نہ کرنے کی قید کا کیا فائدہ ہے؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لِمَ تَقُولُونَ مَا لَا تَفۡعَلُونَ ٢\nنخعی نے کہا: ان تینوں آیتوں نے مجھےدوسروں کو نصیحت کرنے سے روک رکھا ہے: ﴿أَتَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبِرِّ وَتَنسَوۡنَ أَنفُسَكُمۡ وَأَنتُمۡ تَتۡلُونَ ٱلۡكِتَٰبَۚ أَفَلَا تَعۡقِلُونَ﴾ [البقرة: ۴۴]، ﴿وَمَآ أُرِيدُ أَنۡ أُخَالِفَكُمۡ إِلَىٰ مَآ أَنۡهَىٰكُمۡ عَنۡهُ﴾ [هود: ۸۸]، ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لِمَ تَقُولُونَ مَا لَا تَفۡعَلُونَ﴾\" (القرطبی: ۲۰؍۴۳۶)\nان آیتوں کے ڈر سے سلف کی کیا حالت تھی؟ ذکر کیجئے.\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لِمَ تَقُولُونَ مَا لَا تَفۡعَلُونَ ٢\nبھلائی کا حکم دینے والے کے لئے مناسب ہے کہ سب سے پہلے وہ خود اس پر عمل کرے، اور برائی سے روکنے والے کے لئے بھی کہ وہ سب سے زیادہ اس برائی سے دور رہے۔ (السعدی: ۸۵۸)\nایک داعی مومن اس آیت سے کیا کیا استفادہ کر سکتا ہے؟\nإِنَّ ٱللَّهَ يُحِبُّ ٱلَّذِينَ يُقَٰتِلُونَ فِي سَبِيلِهِۦ صَفّٗا كَأَنَّهُم بُنۡيَٰنٞ مَّرۡصُوصٞ ٤\nمجاہدین کی صفیں کچھ یوں منظم و مرتب ہونگی کہ اس سے تمام مجاہدین کے ما بین مساوات کا درس ملے، باہم تقویت حاصل ہو، دشمنوں میں دہشت پھیلے ، ایک دوسرے کو اس سے نشاط ملے ۔ (السعدی: ۸۵۸)\nدوران قتال سیسہ پلائی ہوئی عمارت کے مانند صف بندی کرنے کی حکمت کیا ہے؟\nكَأَنَّهُم بُنۡيَٰنٞ مَّرۡصُوصٞ ٤\nقتادہ نے کہا: کیا تم صاحب عمارت کو نہیں دیکھتے کہ وہ اپنی عمارت میں کوئی خلل پسند نہیں کرتا ہے ،اسی طرح اللہ تعالیٰ بھی پسند نہیں کرتا ہے کہ اس کے کسی امر میں اختلاف ہو، اللہ تعالیٰ نے قتال ولڑائی میں اورنماز میں مومنوں کی صف بندی کی ہے، چنانچہ تم اللہ کے حکم کو لازم پکڑو، کیونکہ جو شخص اسے اختیار کرے گا اس کے لئے اس میں حفاظت ہے ۔(ابن کثیر: ۴؍۳۵۹)\nاللہ تعالیٰ نے مؤمنوں کو دو جگہوں میں خاص ترتیب وتنظیم کا حکم دیا ہے، وہ دونوں کیا ہیں؟\nفَلَمَّا زَاغُوٓاْ أَزَاغَ ٱللَّهُ قُلُوبَهُمۡ\nاس آیت سے یہ بات عیاں ہوتى ہے کہ اللہ تعالیٰ کا اپنے بندوں کو گمراہ کرنا اس کی طرف سے بندوں پر ظلم نہیں ہے، اور نہ ہی ان کے لئے اس میں کسی حجت کی گنجائش ہے، یہ صرف ان کے اپنے کرتوتوں کی وجہ سے ہے، کیونکہ خود وہ -معلوم ہوجانے کے بعد - اپنے اوپر ہدایت کا دروازہ بندکر لیتے ہیں ، تو اللہ تعالیٰ انہیں اس طرح گمراہ اور ٹیڑھا کرکے اس کا بدلہ دے رہا ہے،کہ اسے یہ اپنے اوپر سے ٹال نہیں سکتے ہیں۔(السعدی: ۸۵۹)\nاس آیت میں رد ہے اس شخص پر جو تقدیر سے اپنی گمراہی وانحراف کے جواز پر استدلال کرتا ہے، اس کی وضاحت کیجئے.\nwords\nيُبَايِعنَكَوه آپ سے عهد كرتے هيں.\nبِبُهتَانٍ يَفتَرِينَهُاپني طرف سے گھڑا بهتان(شوهروں كي اولاد ميں غير كي اولاد شامل كرنا).\nلاَ تَتَوَلَّواانهيں اپنے دوست نه بناؤ.\nكَبُرَ مَقتًابهت بڑا بغض/ بڑا گناه.\nمَرصُوصٌچونا گچ ؛اور سيدھي ديوار جس ميں كوئي سوراخ نه هو.\nزَاغُواوه علم هوتے هوئے حق سے ڈھل گئے."],[552,"§الصف\ndeeds\nاصلاح امت اور خیر كے كاموں میں مال خرچ كرنا بھى جہاد ہے، لہٰذا كچھ مال اس ادارہ کو دیجئے جو امت محمدیہ كى شان بلندکرنے کے لئے کام کررہا ہو.\nكسى كافر كو اسلام کی دعوت دیں.\nدعا كریں كہ الله تعالىٰ آپ كو اپنے انصار میں سے بنائے.\nguid\nالله تعالىٰ پر جھوٹ باندھنے سے بچنا.\nنفع بخش تجارت كو لازم پكڑیں.\nخیر كے كاموں میں سابقہ امتوں كى مشابہت اختیار كرنا.\nrefl\nيُرِيدُونَ لِيُطۡفِـُٔواْ نُورَ ٱللَّهِ بِأَفۡوَٰهِهِمۡ\nیعنى وه باطل كےذریعے حق كو رد كرنا چاہتےہیں ، اس میں ان كى مثال اس شخص جیسى ہے جو سورج كى شعاعوں کو اپنے منہ سے بجھانا چاہتاہے، تو جیسا یہ محال ہے اسی طرح وہ بھی محال ہے۔ (ابن كثیر: ۴؍۳۶۱)\nتشبیہ کی اس صورت كى وضاحت كریں جس پر یہ آیت دلالت كرتى ہے.\nوَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوۡ كَرِهَ ٱلۡكَٰفِرُونَ ٨\nجملہ (والله متم نوره)جملہ (يريدون)؛ پر معطوف ہے، جس میں اس بات كى خبر دى گئى ہے كہ کافر اپنے مقصد میں كامیاب نہیں ہوسكتےہیں، اور یہ دین پورا ہوكر رہےگا، یعنى پورے طور سے پھیل جائےگا۔ (ابن عاشور: ۲۸؍۱۹۰)\nالله تعالىٰ كے قول:(والله متم نوره)كے اندر كون سى بشارت ہے؟\nهُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ ٩\nیہ بات معلوم ہے كہ الله تعالىٰ نے اس دین كو تمام ادیان پر غالب كرنے كا وعده كیا ہے ، یہ علم وبیان اور سیف وسنان كا غلبہ ہے چنانچہ ارشاد بارى ہے: (هو الذي أرسل رسوله بالهدى ودين الحق ليظهره على الدين كله ولو كره المشركون).اسى لئے علماء نے اس غلبہ سے دونوں طرح كا غلبہ مراد لیا ہے ، اور لفظ ظہور سب كو شامل ہے؛ كیونكہ ہدایت كا غلبہ علم وبیان سے ہوتاہے اور دین كا غلبہ طاقت اور عمل سے ہوتاہے۔ (ابن تیمیہ : ۶؍۲۹۷)\nیہ دین دیگر ادیان پر غالب كیسے ہوگا؟\nتُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ١١\nگویا نفوس اپنى زندگى اور بقا كو محبوب سمجھتے ہیں اسى لئے فرمایا: (ذلكم خير لكم إن كنتم تعلمون) (یہ تمہارے لئے بہتر ہے اگر تم سمجھو) یعنى زندگى اور سلامتى كیلئے بیٹھے رہنے سے تمہارے لئے جہاد كرنا زیاده بہتر ہے۔ (ابن القیم: ۳؍۱۵۳)\n(إن كنتم تعلمون)كے ذریعے آیت كیوں ختم کی گئی؟\nتُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡۚ\nیہ معلوم ہے كہ ایمان كامل اس یقینى تصدیق كو كہتےہیں جس كى تصدیق كا الله نے حكم دیا ہے جو کہ بدنی اعمال كو لازم ہے ، اور بہترین بدنى اعمال میں سے جہادفى سبیل الله ہے، اسى لئے فرمایا: (وتجاهدون في سبيل الله بأموالكم وأنفسكم). (السعدى: ۸۶۰)\nآیت نے ایمان اور جہاد كو ایك ساتھ جوڑ دیا ہے ، تودونوں میں كیا تعلق ہے؟\nيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡ وَيُدۡخِلۡكُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ وَمَسَٰكِنَ طَيِّبَةٗ فِي جَنَّٰتِ عَدۡنٖۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ١٢\nیہاں گھروں كا ذكر خصوصى طور پر كیا گیا كیونكہ جہاد میں جانےسے گھروں كو چھوڑ نا پڑتاہے، اسى لئے ان سے اس وقتی و فانى گھر كے بدلے ہمیشہ والے گھروں كا وعده كیا گیا ۔ (ابن عاشور: ۲۸؍۱۹۵)\nبالخصوص گھروں كا ذكر كیوں كیا گیا؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُوٓاْ أَنصَارَ ٱللَّهِ\nالله تعالىٰ اپنے مومن بندوں كو حكم دےرہا ہے كہ وه ہر حال میں اپنے قول، فعل، جان اور مال كے ذریعے الله كے مددگار بن جائیں ۔ (ابن كثیر: ۴؍۳۶۱)\nكیا الله كى مدد كسى زمانے یا كسى پہلو كےساتھ خاص ہے؟\nwords\nافتَرَىجھوٹ گھڑ لايا.\nنُورَ اللهِوه حق جو رسول الله صلی اللہ علیہ وسلم لے كر آئے هيں.\nبِأَفوَاهِهِماپني جھوٹي باتوں سے.\nمُتِمُّ نُورِهِحق كو ظاهر كرنے اور دين كو پورا كرنے والا هے.\nالدِّينِ كُلِّهِاس كے مخالف تمام اديان.\nلِلحَوَارِيِّينَحضرت عيسي عليه السلام كے خاص ساتھي.\nظَاهِرِينَغالب."],[553,"§الجمعہ\ndeeds\nالله كے اسمائے حسنى (القدوس) (العزيز) (الحكيم)،كےساتھ دعا كریں، اور ان سے كیا ایمانى اثرات مرتب ہوتےہیں انہیں سیكھیں.\nرازدارى میں كوئى ایسا عمل كریں جسے آپ كےعلاوه كوئى نہ جان سكے.\nالله سے حسن خاتمہ كى دعا مانگیں.\nguid\nایك داعى كا كام یہ ہے كہ كتاب وسنت كى روشنى میں لوگوں كى علمى اور عملى پیمانے پر تربیت كرے.\nتزكیۂ نفس كا اہتمام كرنا.\nكیا ہى برى مثال ہے اس شخص كى جو اپنے علم كے مطابق عمل نہ كرے.\nrefl\nيُسَبِّحُ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ ٱلۡمَلِكِ ٱلۡقُدُّوسِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ١\nدوسرى سورتوں میں تسبیح فعل ماضى كےساتھ ہے جبكہ اس سورت میں فعل مضارع كےساتھ ہے ، اس کی مناسبت یہ ہے كہ اس سورت كا مقصد نماز جمعہ كى فضیلت بتانا ہے، اور ان لوگوں كى مذمت كرنا ہے جو نماز چھوڑ كر تجارت یا لہو ولعب کے لئے چلےگئےتھے، اسى مناسبت سے بیان كیا كہ آسمان اور زمین والے سب الله كى تسبیح ہمیشہ اور مسلسل بیان كرتےہیں ، گویا اس سے ان لوگوں كى طرف اشاره ہے جنہوں نے نماز جمعہ پورى نہیں كى۔ (ابن عاشور: ۲۸؍۲۰۶)\nاس سورت میں تسبیح كا فعل (يُسَبِّحُ) مضارع كیوں آیا ہے جبكہ دوسرى سورتوں میں ماضى آیا ہے؟\nيُسَبِّحُ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ\nالله تعالىٰ خبر دےرہا ہے كہ آسمان وزمین كى سارى مخلوقات چاہے وه بولنے والى ہوں یا جمادات ہوں سب اس كى تسبیح بیان كررہى ہیں۔ (ابن كثیر: ۴؍۳۶۳)\nكیا الله كى تسبیح صرف بولنے والى مخلوق كرتى ہے؟\nهُوَ ٱلَّذِي بَعَثَ فِي ٱلۡأُمِّيِّۧنَ رَسُولٗا مِّنۡهُمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُواْ مِن قَبۡلُ لَفِي ضَلَٰلٖ مُّبِينٖ ٢\nسب سےپہلے تلاوت كا ذكر كیا ؛ كیونكہ تبلیغ دعوت میں سب سے پہلے وحى كى تبلیغ ہوتى ہے، دوسرے نمبر پر تزكیہ كا ذكر كیا ؛ كیونكہ دعوت كى ابتدا معنوى گندگى سے پاک کرنے سے ہوتى ہے اور معنوی گندگی سے مراد شرك اور سارے برے اعمال و اخلاق ہیں ، پھر اس كےبعد قرآن كى تعلیم كا ذكر كیا ؛ كیونكہ قرآن كے ذریعے آپ ان کے لئے اسكے مقاصد اور مفاہیم كو واضح كریں گے۔ (ابن عاشور: ۲۸؍۲۰۹)\nعبارت كى ابتداكیوں سب سے پہلے تلاوت سے كى ، پھر تزكیہ اور پھر كتاب وحكمت كى تعلیم سے ؟\nهُوَ ٱلَّذِي بَعَثَ فِي ٱلۡأُمِّيِّۧنَ رَسُولٗا مِّنۡهُمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُواْ مِن قَبۡلُ لَفِي ضَلَٰلٖ مُّبِينٖ ٢\nكتاب یعنى قرآن كا مقصد اسے سمجھنا اور اس پر عمل كرنا ہے، یعنی اس کا مقصد ایسا علم جو عمل سے مزین ہو، اور ایسا عمل جو معقول اور منقول دونوں علم كے ذریعے مضبوط و بے خلل ہو، تاکہ یہ لوگ ہر چیز كو اس كے محكم جگہوں پر ركھ سكیں ، اوربنو اسرائیل کی طرح کتاب سے نہ بھٹکیں۔ ورنہ ان كى بھى مثال اس گدھے جیسى ہوجائےگی جو كتابوں كو اٹھائےہوئے ہو۔ اور رسول الله صلی اللہ علیہ وسلم كیلئے بطور معجزه اگر صرف یہى كتاب ہوتى تو کافی ہوتا۔ (البقاعى: ۲۰؍۵۱)\nایك مسلمان قرآن كریم سے پورے طور پر فائده كیسے اٹھا سكتاہے؟\nمَثَلُ ٱلَّذِينَ حُمِّلُواْ ٱلتَّوۡرَىٰةَ ثُمَّ لَمۡ يَحۡمِلُوهَا كَمَثَلِ ٱلۡحِمَارِ يَحۡمِلُ أَسۡفَارَۢاۚ بِئۡسَ مَثَلُ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ٥\nالله تعالىٰ مذمت بیان كرتےہوئے فرماتا ہے ان یہودیوں كى جنہیں توارت دیا گیا اور اس پر عمل كرنے كیلئے انہیں ابھارا گیا لیكن انہوں نے اس پر عمل نہیں كیا تو ان كى مثال اس گدھے جیسى ہوگئى جو كتابوں كا گٹھر لاد كر چل رہاہو، یعنى وه حسى طور پر كتابوں كو لادےہوئے ہے لیكن ان میں ہے کیا؟ اسے كچھ پتہ نہ ہو ، اسى طرح یہ لوگ بھی ہیں كہ یہ تورات كو لئےہوئےہیں،اس کے الفاظ یاد ہیں لیکن اسے نہ تو سمجھا اور نہ ہى اسكے تقاضوں پر عمل کیا۔ (ابن كثیر: ۴؍۳۶۴)\nكیا وه حافظ قرآن جو اسے یاد ركھتا ہے ، لیكن اسے نہ تو سمجھتا ہے ، نہ اس میں غور وفكر كرتاہے اور نہ ہى اس پر عمل كرتا ہے وه اہل قرآن میں شمار كیا جائےگا؟\nمَثَلُ ٱلَّذِينَ حُمِّلُواْ ٱلتَّوۡرَىٰةَ ثُمَّ لَمۡ يَحۡمِلُوهَا كَمَثَلِ ٱلۡحِمَارِ يَحۡمِلُ أَسۡفَارَۢاۚ\nیہ مثال گرچہ یہودیوں كیلئےہے لیكن معنوى اعتبار سے یہ مثال اس شخص كیلئے بھى ہے جو قرآن کا علم ركھتا ہے پر اس پر عمل نہیں كرتا، نہ اسكا حق ادا كرتاہے، اور نہ ہى اسكا اس طرح خیال كرتا ہے جیسا كہ كرنا چاہئے۔ (القاسمی: ۹؍۲۲۹)\nكیا یہ مثال صرف اہل تورات كے ساتھ خاص ہے؟\nمَثَلُ ٱلَّذِينَ حُمِّلُواْ ٱلتَّوۡرَىٰةَ ثُمَّ لَمۡ يَحۡمِلُوهَا كَمَثَلِ ٱلۡحِمَارِ يَحۡمِلُ أَسۡفَارَۢاۚ\nمیمون بن مہران نے كہا: گدھے كو پتہ نہیں ہوتا كہ اس كى پشت پر كتابوں كا بنڈل ہے یا كوڑے كا ڈھیر، اسى طرح یہودى ہیں۔ (الشوكانى: ۵؍۲۲۵)\nمیمون كے قول كى روشنى میں بتلائیے كہ یہودیوں كو گدھوں سے تشبیہ دینے کا سبب کیا ہے؟\nwords\nيُسَبِّحُوه هراس چيز سے الله تعاليٰ كي تنزيه بيان كرتا هے جو اس كے شايان شان نهيں.\nالقُدُّوسِهر عيب سے پاك.\nالعَزِيزِقوي اور غالب.\nالأُمِّيِّينَعرب ؛ جن كے پاس كوئي كتاب نه تھي۔ وه پڑهنا نه جانتے تھے.\nلَمَّا يَلحَقُوا بِهِميعني ابھي تك وه نهيں آئے؛ عنقريب آئيں گے.\nأَسفَارًاكتابيں.\nبِئسَ مَثَلُ القَومِبهت بري مثال ان لوگوں كي هے."],[554,"§الجمعہ ، المنافقون\ndeeds\nزیاده سے زیاده تسبیح و تہلیل اورالله كا ذكر كریں.\nجو كچھ ہاتھ میں ہے اسے اذان ہوتے ہی چھوڑ دیں اور فورا ً مسجد كا رخ كریں.\nاپنے اہل وعیال اور اپنے ساتھیوں كو منافقین كے خطرے سے آگاه كریں اور بتائیں كہ یہ دین كے دشمن ہیں.\nguid\nالله تعالىٰ كا زیاده سے زیاده ذكر كرنا كامیابى كا راستہ ہے.\nمنافقین كى ایك علامت جھوٹ بولنا ہے.\nشكل وصورت سے دھوكہ نہیں كھانا چاہئے ، كیونكہ اصل اعتبار حقائق كا ہوتا ہے.\nrefl\nفَٱسۡعَوۡاْ إِلَىٰ ذِكۡرِ ٱللَّهِ وَذَرُواْ ٱلۡبَيۡعَۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ٩\nنماز كا ذكر نہ كركے الله كے ذكر كو ترجیح دى گئى جیسا كہ بعد میں (فإذا قضيت الصلاة) كہہ كر نماز كا ذكر كیا گیا تاكہ اس سے خطبہ اور نماز دونوں مقصد حاصل ہوجائے ۔ (ابن عاشور: ۲۸؍۲۲۵)\nیہاں اللہ کے ذکر کا کیا مقصد ہے ؟\nفَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُواْ فِي ٱلۡأَرۡضِ وَٱبۡتَغُواْ مِن فَضۡلِ ٱللَّهِ\nعراك بن مالك رضی اللہ عنہ جب جمعہ كى نماز سے فارغ ہوتے تو مسجد كےدروازے پر كھڑے ہوكر یہ دعا كرتے: “اَللّٰهُمَّ اِنِّيْ أَجَبْتُ دَعْوَتَكَ، وَصَلَّيْتُ فَرِيْضَتَكَ، وَانْتَشَرْتُ كَمَا أَمَرْتَنِيْ، فَارْزُقْنِيْ مِنْ فَضْلِكَ وَاَنْتَ خَيْرُ الرَّازِقِيْنَ”۔ (ابن كثیر: ۴؍۳۶۷)\nعراك بن مالك رضی اللہ عنہ اس آیت پر كیسے عمل كرتےتھے؟\nفَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُواْ فِي ٱلۡأَرۡضِ وَٱبۡتَغُواْ مِن فَضۡلِ ٱللَّهِ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ ١٠\nتجارت میں مشغول ہوجانے میں چونكہ الله كے ذكر سے غفلت كا امكان ہے اسى لئے زیاده سے زیاده ذكر کا حكم دیاگیاہے۔ (السعدى: ۸۶۳)\nزمین میں پھیل جانے اور رزق تلاش كرنے كے حكم كےبعد اس آیت كے آخر میں الله كا ذكر كرنے كا حكم كیوں دیا گیا؟\nوَإِذَا رَأَوۡاْ تِجَٰرَةً أَوۡ لَهۡوًا ٱنفَضُّوٓاْ إِلَيۡهَا وَتَرَكُوكَ قَآئِمٗاۚ قُلۡ مَا عِندَ ٱللَّهِ خَيۡرٞ مِّنَ ٱللَّهۡوِ وَمِنَ ٱلتِّجَٰرَةِۚ وَٱللَّهُ خَيۡرُ ٱلرَّٰزِقِينَ ١١\nطاعت الٰہى پر صبر كرنے سے رزق نہیں جائےگا ، كیونكہ الله تعالىٰ بہتر روزى دینےوالا ہے، چنانچہ جو الله سے ڈرےگا اسے وه ایسى جگہ سے روزى دے دےگا جس كا اسے گمان بھى نہ ہوگا۔ (السعدى: ۸۶۳)\nآیت كےاندر اس بات كى طرف اشاره ہے كہ الله كا تقوىٰ روزى كے اسباب میں سےہے، اس كى وضاحت كریں.\nإِذَا جَآءَكَ ٱلۡمُنَٰفِقُونَ قَالُواْ نَشۡهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِۗ وَٱللَّهُ يَعۡلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشۡهَدُ إِنَّ ٱلۡمُنَٰفِقِينَ لَكَٰذِبُونَ ١\nالله تعالىٰ نے منافقوں پر جھوٹ كى گواہى دى ہے جبكہ بظاہر ان كى بات حق ہے ؛ كیونكہ ان كا باطن ان كے ظاہر کو جھٹلا رہا ہے، اس لئے كہ اعمال كا دار ومدار نیتوں پر ہے۔ (الشنقیطی: ۸؍۱۸۸)\nالله تعالىٰ نے ان منافقوں پر جھوٹ كى گواہى كیوں دى؟\n۞وَإِذَا رَأَيۡتَهُمۡ تُعۡجِبُكَ أَجۡسَامُهُمۡۖ وَإِن يَقُولُواْ تَسۡمَعۡ لِقَوۡلِهِمۡۖ كَأَنَّهُمۡ خُشُبٞ مُّسَنَّدَةٞۖ يَحۡسَبُونَ كُلَّ صَيۡحَةٍ عَلَيۡهِمۡۚ هُمُ ٱلۡعَدُوُّ فَٱحۡذَرۡهُمۡۚ قَٰتَلَهُمُ ٱللَّهُۖ أَنَّىٰ يُؤۡفَكُونَ ٤\nیہ ایسے لوگ ہیں جو دیكھنے میں خوبصورت ٹیك لگائى ہوئى لكڑى لگتےہیں ، انہیں دیوار سے ایسى ٹیك لگائى ہوئى لكڑى سے تشبیہ دى گئى جو نہ سنتےہیں اور نہ سمجھتے ہیں، جن كى شبیہ تو ہے مگر روح سے خالى، جسم تو ہے مگر عقل سے عاری۔ اور كہاگیا: انہیں تشبیہ در اصل اس لكڑى سے دى گئى ہے جو سڑ چكى ہو اور دوسرى چیز سے ٹیك لگائى ہو جس كے بارے میں نہ پتہ ہو كہ اندر كیا ہے۔(القرطبى: ۲۰؍۵۰۰)\nٹیك لگائى ہوئى لكڑى سے ان كى تشبیہ دینے كى كیا وجہ ہے؟\nهُمُ ٱلۡعَدُوُّ\nیہى حقیقى دشمن ہیں؛ كیونكہ كھلا دشمن اس دشمن سے زیاده ہلكا ہے جس كا پتہ نہ ہو اور ساتھ ہى وہ دھوكےباز چالباز بھى ہو، اور اظہار كرے كہ وه دوست ہے جب كہ پکا دشمن ہے۔ (سعدى: ۸۶۴)\nالله تعالىٰ نے منافقوں كےبارے میں یہ كیوں كہا كہ وہى حقیقى دشمن ہیں؟\nwords\nوَذَرُواچھوڑ دو.\nانفَضُّوا إِلَيهَاآپ كو چھوڑ كراس طرف چلے گئے.\nفَطُبِعَمهر لگادي گئي.\nكَأَنَّهُم خُشُبٌ مُسَنَّدَةٌگويا ديواركے ساتھ كھڑي لكڑيان هيں۔ ايمان سے خالي هونے كي وجه سے.\nكُلَّ صَيحَةٍ عَلَيهِمهر بلند آواز كو اپنے خلاف سمجھتے هيں (شدت خوف كي وجه سے )."],[555,"§المنافقون\ndeeds\nكوئى درس یا شرعى محاضره(لکچر) تیار كریں.\nاپنے لئےمومنوں اور مومنات كیلئے استغفار کیجئے.\nكسى داعى یا طالب علم كى كفالت كیلئے كسى رفاہى سوسائٹى میں چنده دیں تاكہ منافقین کی صفات سے دور ره سكیں.\nguid\nعزت صرف الله ہى سے مل سكتى ہے، جو عزت چاہتا اسے اسكے مالك ہی سے مانگنا چاہئے.\nمال واولاد اللہ سے دوری کا سبب بن سکتے ہیں.\nحسن خاتمہ كا حریص ہونا چاہئے.\nrefl\nوَلِلَّهِ خَزَآئِنُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَٰكِنَّ ٱلۡمُنَٰفِقِينَ لَا يَفۡقَهُونَ ٧\n(ولكن المنافقين لا يفقهون) اس استدراك كا مقصد منافقین کے اہم وہم کا ازالہ ہے اور وہ یہ ہے كہ جب منافقوں نے كہا: (لا تنفقوا على من عند رسول الله حتى ينفضوا) (جو لوگ رسول الله كےپاس ہیں ان پر خرچ نہ كرو جب تك كہ وه وہاں سے ہٹ نہ جائیں) تو انہوں نے علم ویقین سے کہا كہ جو لوگ رسول الله صلی اللہ علیہ وسلم كےپاس رہتےہیں اگر ان پر خرچ نہ كیا جائے تو وہاں سے وه نكل جائیں گے، اوراس بنیادپر کہا كہ ان پر خرچ كرنے كى طاقت صرف انہی كےاندر ہے، كیونكہ وه مالدار ہیں۔ اس وہم كو دور كرنے كیلئے كہاگیا كہ منافقین نہیں سمجھتے، کیونکہ وہ بھول گئے کہ رزق اور فقركےاسباب متعدد ہوتےہیں۔ (ابن عاشور: ۲۸؍۲۴۸)\n(ولكن المنافقين لا يفقهون)ے ذریعے استدراك كا كیا فائده ہے؟\nوَلِلَّهِ ٱلۡعِزَّةُ وَلِرَسُولِهِۦ وَلِلۡمُؤۡمِنِينَ وَلَٰكِنَّ ٱلۡمُنَٰفِقِينَ لَا يَعۡلَمُونَ ٨\nلوگ عزت بادشاہوں کے درباروں میں طلب کرتے ہیں، جبکہ عزت صرف اللہ کی فرمانبرداری میں ہے ۔ حسن بصری کہاکرتے تھے کہ اگرچہ ان کے پاس تیز رو ترکی گھوڑےہوں، خچروں کی کثرت ہو لیکن معصیت کی ذلت و خواری ان پر مسلط کردی گئی ہے اور اللہ تعالیٰ اپنے نافرمانوں کو ہرصورت میں رسوا کرے گا۔ (ابن تیمیہ: ۶؍۳۱۲)\nحقیقی عزت کہاں تلاش کی جائے؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُلۡهِكُمۡ أَمۡوَٰلُكُمۡ وَلَآ أَوۡلَٰدُكُمۡ عَن ذِكۡرِ ٱللَّهِۚ\nالله تعالىٰ نے جب منافقین كى برائیوں كو بیان كردیا تو اب خطاب مومنوں كو ہے انہیں الله كے ذكر میں رغبت دلاتےہوئے فرمایا: (يا أيها الذين آمنوا لا تلهكم أموالكم ولا أولادكم عن ذكر الله) تو اس آیت میں الله نے انہیں منافقوں كےاخلاق سے ڈرایا جنہیں ان كے مال اور اولاد نے الله كے ذكر سے غافل كردیا ہے۔ (الشوكانى: ۵؍۲۳۳)\nاس آیت كا ماقبل سے كیا تعلق ہے؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُلۡهِكُمۡ أَمۡوَٰلُكُمۡ وَلَآ أَوۡلَٰدُكُمۡ عَن ذِكۡرِ ٱللَّهِۚ\nالله كےذكر سے غافل كرنے والى چیزوں میں ما ل واولاد كا خصوصى طور پر ذكر كیا گیا ، اور ان میں اس طرح منہمک رہنے سے منع کیاگیا جو اللہ کی یاد سے غافل کردے كیونكہ لوگ مال کمانے اور اسے بڑھانے پر زیاده توجہ دیتےہیں اور اس میں ان كى مشغولیت اولاد میں مشغولیت سے زیاده ہوتى ہے، اور اس لئے بھی مال کا خصوصی ذکر ہوا ہے کیونکہ مال كمانے اور بڑھانے میں مشغول ہوناجس طرح الله كے ذكر سے غافل كرتاہے اسى طرح اسے ذخیر ه كرنے کا چكر بھی اللہ كے راستے میں خرچ كرنے سے غافل كردیتا ہے جس كا كہ الله نے حكم دیا ہے۔ (ابن عاشور: ۲۸؍۲۵۱)\nالله كے ذكر سے غافل كرنے والى چیزوں میں صرف مال واولاد ہى كا ذكر كیوں كیا گیا ؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُلۡهِكُمۡ أَمۡوَٰلُكُمۡ وَلَآ أَوۡلَٰدُكُمۡ عَن ذِكۡرِ ٱللَّهِۚ\nہمیشہ اللہ کا ذکر کرنا اس کی دائمی محبت کا باعث ہے، دل کے لئے اللہ کا ذکر ویسے ہی ہے جیسے کھیتی کے لئے پانی، کہ اس کے بغیرکھیتی ممکن نہیں ہے۔ذکرِ الٰہی کی کئی قسمیں ہیں: ۱۔اللہ کے اسماء و صفات کے ذریعہ اسے یاد کرنا، اور ان کے واسطے اللہ کی تعریف بیان کرنا۔ ۲۔اللہ کی تسبیح، تحمید، تکبیر، تہلیل اور تمجید بیان کرنا۔ اور عموماًعلمائے متاخرین ذکرِالٰہی سے یہی مراد لیتے ہیں۔ ۳۔ اللہ کے احکام، اس کے اوامر و نواہی کے ذریعہ اللہ کو یاد رکھنایہ عموماً اہل علم کرتے ہیں ۴۔اللہ کے کلام کے ذریعہ اللہ کویادرکھنا افضل ترین ذکر ہے۔ ۵۔دعاء، استغفار اور اللہ سے آہ وزاری کے ذریعہ اسے یاد کرنا۔ ذکر کی یہ پانچ قسمیں ہیں’’ ۔(ابن القیم: ۳؍۱۵۷-۱۵۸)\nذکرِ الہٰی کی اہمیت اور اس کے اقسام بیان کیجئے ؟\nوَأَنفِقُواْ مِن مَّا رَزَقۡنَٰكُم\nیہ اس بات پر دلالت كرتاہے كہ الله تعالىٰ نے بندوں كو ایسى چیز كے خرچ كرنے كا مكلف نہیں بنایا جس سے وه مشقت میں پڑیں اور تكلیف ہو، بلكہ انہیں اسى میں سےکچھ خرچ كرنے كا حكم دیا جو اسے روزى دے ركھى ہے اور وه ان كے لئےآسان بھى ہے اور الله نےاس کے اسباب بھى آسان كردئیے ہیں۔(السعدى: ۸۶۵)\nاس آیت میں (مِنْ) تبعیضیہ لانے كا كیا فائده ہے؟\nمِّن قَبۡلِ أَن يَأۡتِيَ أَحَدَكُمُ ٱلۡمَوۡتُ فَيَقُولَ رَبِّ لَوۡلَآ أَخَّرۡتَنِيٓ إِلَىٰٓ أَجَلٖ قَرِيبٖ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّٰلِحِينَ ١٠\nہر كوتاه شخص موت كے وقت نادم ہوگا، اور درازئ وقت كا سوال كرےگا – گرچہ تھوڑا ہى وقت مل جائے- تاكہ توبہ كرلے اور مافات كى تلافى كرلے۔ (ابن كثیر: ۴؍۳۷۳)\nكیا موت كےوقت نادم ہونا صرف كافروں كےساتھ خاص ہے؟ نیز اس سے آپ كو كیا فائده ہے؟\nwords\nلَوَّوا رُؤُوسَهُموه ٹھٹھه سے روگرداني كرتے هوئے گردن مروڑتے هيں.\nيَصُدُّونَوه روكتے هيں.\nيَنفَضُّوامتفرق هو جائيں.\nرَجَعنَاهم واپس آئے (غزوه بني مصطلق سے ).\nلاَ تُلهِكُمتمهيں غافل نه كردے.\nلَولاَ أَخَّرتَنِيمجھے مهلت كيوں نه دي.\nأَجَلُهَااس كي موت كا وقت."]])